#[cfg(any(feature = "cuda", test))]
const DEFAULT_CUDA_POOL_RELEASE_THRESHOLD_MB: u64 = 256;
#[cfg(any(feature = "cuda", test))]
const MAX_CUDA_POOL_RELEASE_THRESHOLD_MB: u64 = 4096;
#[cfg(any(feature = "cuda", test))]
const MIB: u64 = 1024 * 1024;

#[cfg(any(feature = "cuda", test))]
fn cuda_pool_release_threshold_bytes(value: Option<&str>) -> Result<u64> {
    let threshold_mb = match value.map(str::trim).filter(|value| !value.is_empty()) {
        Some(value) => value.parse::<u64>().map_err(|_| {
            XrtError::Cuda(format!(
                "XRT_CUDA_POOL_RELEASE_THRESHOLD_MB must be an integer from 0 to {MAX_CUDA_POOL_RELEASE_THRESHOLD_MB}, got `{value}`"
            ))
        })?,
        None => DEFAULT_CUDA_POOL_RELEASE_THRESHOLD_MB,
    };
    if threshold_mb > MAX_CUDA_POOL_RELEASE_THRESHOLD_MB {
        return Err(XrtError::Cuda(format!(
            "XRT_CUDA_POOL_RELEASE_THRESHOLD_MB must be at most {MAX_CUDA_POOL_RELEASE_THRESHOLD_MB}, got {threshold_mb}"
        )));
    }
    threshold_mb
        .checked_mul(MIB)
        .ok_or_else(|| XrtError::Cuda("CUDA memory-pool release threshold overflow".to_string()))
}

impl CudaTransferStats {
    pub fn saturating_sub(self, earlier: Self) -> Self {
        Self {
            host_to_device_calls: self
                .host_to_device_calls
                .saturating_sub(earlier.host_to_device_calls),
            host_to_device_bytes: self
                .host_to_device_bytes
                .saturating_sub(earlier.host_to_device_bytes),
            device_to_host_calls: self
                .device_to_host_calls
                .saturating_sub(earlier.device_to_host_calls),
            device_to_host_bytes: self
                .device_to_host_bytes
                .saturating_sub(earlier.device_to_host_bytes),
            device_to_device_calls: self
                .device_to_device_calls
                .saturating_sub(earlier.device_to_device_calls),
            device_to_device_bytes: self
                .device_to_device_bytes
                .saturating_sub(earlier.device_to_device_bytes),
        }
    }
}

/// Validated geometry for one Qwen3.5 DeltaNet recurrent layer.
///
/// The CUDA implementation intentionally starts with F32 state and a
/// correctness-first, one-token execution contract. Larger fused kernels can
/// replace the implementation without changing this semantic boundary.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CudaDeltaNetGeometry {
    state_size: usize,
    group_count: usize,
    inner_size: usize,
    value_heads: usize,
    conv_kernel: usize,
}

impl CudaDeltaNetGeometry {
    pub fn new(
        state_size: usize,
        group_count: usize,
        inner_size: usize,
        value_heads: usize,
        conv_kernel: usize,
    ) -> Result<Self> {
        if state_size == 0
            || group_count == 0
            || inner_size == 0
            || value_heads == 0
            || conv_kernel == 0
        {
            return Err(XrtError::Shape(
                "CUDA DeltaNet geometry dimensions must be non-zero".to_string(),
            ));
        }
        if inner_size % value_heads != 0 {
            return Err(XrtError::Shape(format!(
                "CUDA DeltaNet inner size {inner_size} is not divisible by value-head count {value_heads}"
            )));
        }
        if value_heads % group_count != 0 {
            return Err(XrtError::Shape(format!(
                "CUDA DeltaNet value-head count {value_heads} is not divisible by Q/K group count {group_count}"
            )));
        }

        let geometry = Self {
            state_size,
            group_count,
            inner_size,
            value_heads,
            conv_kernel,
        };
        for (value, role) in [
            (geometry.state_size, "state size"),
            (geometry.group_count, "group count"),
            (geometry.inner_size, "inner size"),
            (geometry.value_heads, "value-head count"),
            (geometry.conv_kernel, "convolution kernel"),
            (geometry.conv_channels()?, "convolution channels"),
            (geometry.recurrent_state_len()?, "recurrent state length"),
        ] {
            u32::try_from(value).map_err(|_| {
                XrtError::Unsupported(format!(
                    "CUDA DeltaNet {role} {value} exceeds the current u32 kernel limit"
                ))
            })?;
        }
        Ok(geometry)
    }

    pub fn state_size(self) -> usize {
        self.state_size
    }

    pub fn group_count(self) -> usize {
        self.group_count
    }

    pub fn inner_size(self) -> usize {
        self.inner_size
    }

    pub fn value_heads(self) -> usize {
        self.value_heads
    }

    pub fn conv_kernel(self) -> usize {
        self.conv_kernel
    }

    pub fn history(self) -> usize {
        self.conv_kernel - 1
    }

    pub fn head_value_size(self) -> usize {
        self.inner_size / self.value_heads
    }

    pub fn qk_width(self) -> Result<usize> {
        self.state_size
            .checked_mul(self.group_count)
            .ok_or_else(|| XrtError::Shape("CUDA DeltaNet Q/K width overflowed".to_string()))
    }

    pub fn conv_channels(self) -> Result<usize> {
        self.qk_width()?
            .checked_mul(2)
            .and_then(|value| value.checked_add(self.inner_size))
            .ok_or_else(|| {
                XrtError::Shape("CUDA DeltaNet convolution channel count overflowed".to_string())
            })
    }

    pub fn conv_state_len(self) -> Result<usize> {
        self.history()
            .checked_mul(self.conv_channels()?)
            .ok_or_else(|| {
                XrtError::Shape("CUDA DeltaNet convolution state length overflowed".to_string())
            })
    }

    pub fn conv_weight_len(self) -> Result<usize> {
        self.conv_channels()?
            .checked_mul(self.conv_kernel)
            .ok_or_else(|| {
                XrtError::Shape("CUDA DeltaNet convolution weight length overflowed".to_string())
            })
    }

    pub fn recurrent_state_len(self) -> Result<usize> {
        self.inner_size.checked_mul(self.state_size).ok_or_else(|| {
            XrtError::Shape("CUDA DeltaNet recurrent state length overflowed".to_string())
        })
    }
}

