        pub fn inner(&self) -> &Arc<DriverCudaDevice> {
            &self.device
        }

        pub fn transfer_stats(&self) -> CudaTransferStats {
            self.transfer_counters.snapshot()
        }

        pub fn allocation_stats(&self) -> CudaAllocationStats {
            self.allocation_counters.snapshot()
        }

        pub fn reset_allocation_peak(&self) {
            self.allocation_counters.reset_peak_to_current();
        }

        pub fn memory_pool_stats(&self) -> Result<Option<CudaMemoryPoolStats>> {
            self.memory_pool
                .map(|memory_pool| memory_pool.stats(&self.device))
                .transpose()
        }

        pub fn trim_memory_pool_to(&self, min_bytes_to_keep: u64) -> Result<()> {
            let memory_pool = self.memory_pool.ok_or_else(|| {
                XrtError::Unsupported(
                    "CUDA device does not support stream-ordered memory pools".to_string(),
                )
            })?;
            memory_pool.trim_to(&self.device, min_bytes_to_keep)
        }

        fn track_allocation(&self, bytes: usize) -> CudaAllocationLease {
            self.allocation_counters.acquire(bytes)
        }

        pub fn record_event(&self) -> Result<CudaEvent> {
            let event = CudaEvent::new(self.device.clone())?;
            event.record_on_raw_stream(*self.device.cu_stream())?;
            Ok(event)
        }

        pub fn wait_for_event(&self, event: &CudaEvent) -> Result<()> {
            event.ensure_device(&self.device)?;
            event.wait_on_raw_stream(*self.device.cu_stream())
        }

        pub fn create_execution_stream(&self) -> Result<CudaExecutionStream> {
            let stream = self
                .device
                .fork_default_stream()
                .map_err(|err| cuda_error("failed to create CUDA execution stream", err))?;
            Ok(CudaExecutionStream {
                device: self.device.clone(),
                stream,
            })
        }

        pub fn compose_parallel_graphs(
            &self,
            children: &[&CudaGraphExec],
        ) -> Result<CudaGraphExec> {
            if children.len() < 2 {
                return Err(XrtError::Cuda(
                    "parallel CUDA graph composition requires at least two child graphs"
                        .to_string(),
                ));
            }
            if children
                .iter()
                .any(|child| !Arc::ptr_eq(&self.device, &child.device))
            {
                return Err(XrtError::Cuda(
                    "parallel CUDA graph children belong to different devices".to_string(),
                ));
            }
            self.device
                .bind_to_thread()
                .map_err(|err| cuda_error("failed to bind CUDA graph composition context", err))?;

            let driver = unsafe { sys::lib() };
            let mut graph = ptr::null_mut();
            unsafe { driver.cuGraphCreate(&mut graph, 0).result() }
                .map_err(|err| cuda_error("failed to create parallel CUDA graph", err))?;
            for child in children {
                let mut node = ptr::null_mut();
                if let Err(err) = unsafe {
                    driver
                        .cuGraphAddChildGraphNode(&mut node, graph, ptr::null(), 0, child.graph)
                        .result()
                } {
                    unsafe {
                        let _ = driver.cuGraphDestroy(graph);
                    }
                    return Err(cuda_error(
                        "failed to add child to parallel CUDA graph",
                        err,
                    ));
                }
            }

            let mut executable = ptr::null_mut();
            if let Err(err) = unsafe {
                driver
                    .cuGraphInstantiateWithFlags(&mut executable, graph, 0)
                    .result()
            } {
                unsafe {
                    let _ = driver.cuGraphDestroy(graph);
                }
                return Err(cuda_error("failed to instantiate parallel CUDA graph", err));
            }
            let node_count = children.iter().map(|child| child.node_count).sum::<usize>();
            Ok(CudaGraphExec {
                device: self.device.clone(),
                graph,
                executable,
                node_count,
            })
        }

        /// Captures allocation-free work on this device's nonblocking stream.
        ///
        /// # Safety
        ///
        /// Every captured device allocation and loaded function must outlive the returned graph
        /// executable. The capture closure must not allocate, synchronize, or load CUDA modules.
        pub unsafe fn capture_graph<F>(&self, capture: F) -> Result<CudaGraphExec>
        where
            F: FnOnce() -> Result<()>,
        {
            let (graph, node_count) = self.capture_graph_definition(capture)?;
            let driver = sys::lib();
            let mut executable = ptr::null_mut();
            if let Err(err) = driver
                .cuGraphInstantiateWithFlags(&mut executable, graph, 0)
                .result()
            {
                let _ = driver.cuGraphDestroy(graph);
                return Err(cuda_error("failed to instantiate CUDA graph", err));
            }
            if executable.is_null() {
                let _ = driver.cuGraphDestroy(graph);
                return Err(XrtError::Cuda(
                    "CUDA graph instantiation returned a null executable".to_string(),
                ));
            }
            let upload = std::env::var("XRT_CUDA_GRAPH_UPLOAD")
                .ok()
                .is_some_and(|value| {
                    matches!(
                        value.trim().to_ascii_lowercase().as_str(),
                        "1" | "true" | "on" | "enabled"
                    )
                });
            if upload {
                let stream = *self.device.cu_stream();
                if let Err(err) = driver.cuGraphUpload(executable, stream).result() {
                    let _ = driver.cuGraphExecDestroy(executable);
                    let _ = driver.cuGraphDestroy(graph);
                    return Err(cuda_error("failed to upload CUDA graph executable", err));
                }
                if let Err(err) = driver.cuStreamSynchronize(stream).result() {
                    let _ = driver.cuGraphExecDestroy(executable);
                    let _ = driver.cuGraphDestroy(graph);
                    return Err(cuda_error("failed to synchronize CUDA graph upload", err));
                }
            }

            Ok(CudaGraphExec {
                device: self.device.clone(),
                graph,
                executable,
                node_count,
            })
        }

        /// Re-captures a graph and updates an existing executable in place.
        ///
        /// CUDA accepts changed kernel parameters and allocation pointers when the captured graph
        /// topology remains compatible. If the driver rejects the update, the previous executable
        /// and retained graph remain valid.
        ///
        /// # Safety
        ///
        /// Every captured device allocation and loaded function must outlive `executable`. The
        /// capture closure must not allocate, synchronize, or load CUDA modules.
        pub unsafe fn update_graph<F>(
            &self,
            executable: &mut CudaGraphExec,
            capture: F,
        ) -> Result<()>
        where
            F: FnOnce() -> Result<()>,
        {
            if !Arc::ptr_eq(&self.device, &executable.device) {
                return Err(XrtError::Cuda(
                    "CUDA graph executable and capture device belong to different devices"
                        .to_string(),
                ));
            }

            let (graph, node_count) = self.capture_graph_definition(capture)?;
            let driver = sys::lib();
            let mut update_info = sys::CUgraphExecUpdateResultInfo::default();
            if let Err(err) = driver
                .cuGraphExecUpdate_v2(executable.executable, graph, &mut update_info)
                .result()
            {
                let _ = driver.cuGraphDestroy(graph);
                return Err(cuda_error("failed to update CUDA graph executable", err));
            }
            if update_info.result != sys::CUgraphExecUpdateResult::CU_GRAPH_EXEC_UPDATE_SUCCESS {
                let result = update_info.result;
                let _ = driver.cuGraphDestroy(graph);
                return Err(XrtError::Cuda(format!(
                    "CUDA graph executable update was rejected: {result:?}"
                )));
            }

            let old_graph = std::mem::replace(&mut executable.graph, graph);
            executable.node_count = node_count;
            let _ = driver.cuGraphDestroy(old_graph);
            Ok(())
        }

        unsafe fn capture_graph_definition<F>(&self, capture: F) -> Result<(sys::CUgraph, usize)>
        where
            F: FnOnce() -> Result<()>,
        {
            self.device
                .bind_to_thread()
                .map_err(|err| cuda_error("failed to bind CUDA graph capture context", err))?;
            self.device.synchronize().map_err(|err| {
                cuda_error("failed to synchronize before CUDA graph capture", err)
            })?;

            let stream = *self.device.cu_stream();
            let driver = sys::lib();
            driver
                .cuStreamBeginCapture_v2(
                    stream,
                    sys::CUstreamCaptureMode::CU_STREAM_CAPTURE_MODE_THREAD_LOCAL,
                )
                .result()
                .map_err(|err| cuda_error("failed to begin CUDA graph capture", err))?;

            let capture_result = catch_unwind(AssertUnwindSafe(capture));
            let mut graph = ptr::null_mut();
            let end_result = driver.cuStreamEndCapture(stream, &mut graph).result();

            match capture_result {
                Ok(Ok(())) => {}
                Ok(Err(err)) => {
                    if !graph.is_null() {
                        let _ = driver.cuGraphDestroy(graph);
                    }
                    return Err(err);
                }
                Err(payload) => {
                    if !graph.is_null() {
                        let _ = driver.cuGraphDestroy(graph);
                    }
                    resume_unwind(payload);
                }
            }

            if let Err(err) = end_result {
                if !graph.is_null() {
                    let _ = driver.cuGraphDestroy(graph);
                }
                return Err(cuda_error("failed to end CUDA graph capture", err));
            }
            if graph.is_null() {
                return Err(XrtError::Cuda(
                    "CUDA graph capture returned a null graph".to_string(),
                ));
            }

            let mut node_count = 0usize;
            if let Err(err) = driver
                .cuGraphGetNodes(graph, ptr::null_mut(), &mut node_count)
                .result()
            {
                let _ = driver.cuGraphDestroy(graph);
                return Err(cuda_error("failed to query CUDA graph nodes", err));
            }
            if node_count == 0 {
                let _ = driver.cuGraphDestroy(graph);
                return Err(XrtError::Cuda(
                    "CUDA graph capture produced no executable nodes".to_string(),
                ));
            }

            Ok((graph, node_count))
        }

        pub fn alloc_decode_params(
            &self,
            capacity: usize,
            vocab_size: usize,
        ) -> Result<CudaDecodeParams> {
            if capacity == 0 {
                return Err(XrtError::Shape(
                    "CUDA decode parameter capacity must be positive".to_string(),
                ));
            }
            if vocab_size == 0 {
                return Err(XrtError::Shape(
                    "CUDA decode parameter vocabulary must be positive".to_string(),
                ));
            }
            to_u32(capacity, "CUDA graph decode capacity")?;
            to_u32(vocab_size, "CUDA graph decode vocabulary")?;
            let data = self
                .device
                .htod_copy(vec![0u32; CudaDecodeParams::ELEMENT_COUNT])
                .map_err(|err| cuda_error("failed to allocate CUDA decode parameters", err))?;
            self.transfer_counters.record_host_to_device(
                CudaDecodeParams::ELEMENT_COUNT * std::mem::size_of::<u32>(),
            );
            let allocation =
                self.track_allocation(CudaDecodeParams::ELEMENT_COUNT * std::mem::size_of::<u32>());
            Ok(CudaDecodeParams {
                data,
                _allocation: allocation,
                capacity,
                vocab_size,
            })
        }

        pub fn update_decode_params(
            &self,
            params: &mut CudaDecodeParams,
            token_id: u32,
            position: usize,
            cache_len: usize,
            attend_start: usize,
        ) -> Result<()> {
            let values =
                Self::checked_decode_params(params, token_id, position, cache_len, attend_start)?;
            self.device
                .htod_sync_copy_into(&values, &mut params.data)
                .map_err(|err| cuda_error("failed to update CUDA decode parameters", err))?;
            self.transfer_counters
                .record_host_to_device(std::mem::size_of_val(&values));
            Ok(())
        }

        /// Enqueues a decode-parameter update on the device stream without synchronizing it.
        ///
        /// # Safety
        ///
        /// Work using the previous parameter upload must have completed before this is called
        /// again or before `params` is dropped. Subsequent consumers must use the same stream.
        pub unsafe fn update_decode_params_async(
            &self,
            params: &mut CudaDecodeParams,
            token_id: u32,
            position: usize,
            cache_len: usize,
            attend_start: usize,
        ) -> Result<()> {
            let values =
                Self::checked_decode_params(params, token_id, position, cache_len, attend_start)?;
            self.device
                .htod_copy_into(values.to_vec(), &mut params.data)
                .map_err(|err| cuda_error("failed to enqueue CUDA decode parameters", err))?;
            self.transfer_counters
                .record_host_to_device(std::mem::size_of_val(&values));
            Ok(())
        }

        fn checked_decode_params(
            params: &CudaDecodeParams,
            token_id: u32,
            position: usize,
            cache_len: usize,
            attend_start: usize,
        ) -> Result<[u32; CudaDecodeParams::ELEMENT_COUNT]> {
            if token_id as usize >= params.vocab_size {
                return Err(XrtError::Model(format!(
                    "token id {token_id} exceeds CUDA graph embedding rows {}",
                    params.vocab_size
                )));
            }
            let expected_cache_len = position.checked_add(1).ok_or_else(|| {
                XrtError::Runtime("CUDA graph decode position overflow".to_string())
            })?;
            if cache_len != expected_cache_len {
                return Err(XrtError::Runtime(format!(
                    "CUDA graph decode cache length must equal position + 1: position={position}, cache_len={cache_len}"
                )));
            }
            if cache_len > params.capacity {
                return Err(XrtError::Runtime(format!(
                    "CUDA graph decode cache length {cache_len} exceeds capacity {}",
                    params.capacity
                )));
            }
            if attend_start >= cache_len {
                return Err(XrtError::Shape(format!(
                    "CUDA graph attention start {attend_start} must be less than cache length {cache_len}"
                )));
            }
            Ok([
                token_id,
                to_u32(position, "CUDA graph decode position")?,
                to_u32(cache_len, "CUDA graph decode cache length")?,
                to_u32(attend_start, "CUDA graph attention start")?,
            ])
        }

        pub fn name(&self) -> Result<String> {
            self.device
                .name()
                .map_err(|err| cuda_error("failed to query CUDA device name", err))
        }

        pub fn memory_info(&self) -> Result<(u64, u64)> {
            let (free, total) = driver_result::mem_get_info()
                .map_err(|err| cuda_error("failed to query CUDA memory info", err))?;
            Ok((free as u64, total as u64))
        }

        pub fn upload_bytes(&self, bytes: &[u8]) -> Result<CudaBytes> {
            let data = self
                .device
                .htod_copy(bytes.to_vec())
                .map_err(|err| cuda_error("failed to copy bytes to device", err))?;
            self.transfer_counters.record_host_to_device(bytes.len());
            let allocation = self.track_allocation(bytes.len());
            Ok(CudaBytes {
                data,
                len: bytes.len(),
                capacity_len: bytes.len(),
                _allocation: allocation,
            })
        }

        pub fn upload_f32(&self, values: &[f32]) -> Result<CudaF32Buffer> {
            let data = self
                .device
                .htod_copy(values.to_vec())
                .map_err(|err| cuda_error("failed to copy f32 buffer to device", err))?;
            self.transfer_counters
                .record_host_to_device(std::mem::size_of_val(values));
            let allocation = self.track_allocation(std::mem::size_of_val(values));
            Ok(CudaF32Buffer {
                data,
                len: values.len(),
                capacity_len: values.len(),
                _allocation: allocation,
            })
        }

        pub fn alloc_pinned_f32(&self, len: usize) -> Result<CudaPinnedF32Buffer> {
            if len == 0 {
                return Ok(CudaPinnedF32Buffer {
                    device: Arc::clone(&self.device),
                    ptr: NonNull::dangling(),
                    len,
                });
            }
            let byte_len = checked_mul(
                len,
                std::mem::size_of::<f32>(),
                "CUDA pinned f32 allocation bytes",
            )?;
            self.device
                .bind_to_thread()
                .map_err(|err| cuda_error("failed to bind CUDA pinned allocation context", err))?;
            let mut raw = ptr::null_mut::<c_void>();
            unsafe { sys::lib().cuMemHostAlloc(&mut raw, byte_len, 0).result() }
                .map_err(|err| cuda_error("failed to allocate CUDA pinned f32 staging", err))?;
            let Some(ptr) = NonNull::new(raw.cast::<f32>()) else {
                return Err(XrtError::Cuda(
                    "CUDA pinned allocation returned a null pointer".to_string(),
                ));
            };
            // SAFETY: CUDA returned an allocation of `byte_len == len *
            // size_of::<f32>()`; zero is a valid initialized f32 bit pattern.
            unsafe {
                ptr::write_bytes(ptr.as_ptr(), 0, len);
            }
            Ok(CudaPinnedF32Buffer {
                device: Arc::clone(&self.device),
                ptr,
                len,
            })
        }

        pub fn upload_f32_into(
            &self,
            values: &[f32],
            destination: &mut CudaF32Buffer,
        ) -> Result<()> {
            expect_len(destination.len(), values.len(), "f32 upload destination")?;
            if values.is_empty() {
                return Ok(());
            }
            // A reusable buffer may expose a shorter active logical length
            // than its retained allocation. Copy into that logical prefix;
            // passing the complete allocation to cudarc would assert when a
            // variable-row verifier shrinks from (for example) 16 to 5 rows.
            let mut destination_view =
                destination
                    .data
                    .try_slice_mut(..values.len())
                    .ok_or_else(|| {
                        XrtError::Cuda("failed to slice f32 upload destination".to_string())
                    })?;
            self.device
                .htod_sync_copy_into(values, &mut destination_view)
                .map_err(|err| cuda_error("failed to copy f32 values into device buffer", err))?;
            self.transfer_counters
                .record_host_to_device(std::mem::size_of_val(values));
            Ok(())
        }

        pub fn upload_f32_from_pinned(
            &self,
            source: &CudaPinnedF32Buffer,
            destination: &mut CudaF32Buffer,
        ) -> Result<()> {
            expect_len(destination.len(), source.len(), "pinned f32 upload source")?;
            self.upload_f32_from_pinned_range(source, 0, destination)
        }

        pub fn upload_f32_prefix_from_pinned(
            &self,
            source: &CudaPinnedF32Buffer,
            len: usize,
            destination: &mut CudaF32Buffer,
        ) -> Result<()> {
            if len > source.len() || len > destination.len() {
                return Err(XrtError::Shape(format!(
                    "pinned f32 prefix upload length {len} exceeds source {} or destination {}",
                    source.len(),
                    destination.len()
                )));
            }
            if len == 0 {
                return Ok(());
            }
            let mut destination_view = destination.data.try_slice_mut(..len).ok_or_else(|| {
                XrtError::Runtime(
                    "failed to create pinned f32 prefix upload destination view".to_string(),
                )
            })?;
            self.device
                .htod_sync_copy_into(&source.as_slice()[..len], &mut destination_view)
                .map_err(|err| {
                    cuda_error("failed to copy pinned f32 prefix into device buffer", err)
                })?;
            self.transfer_counters
                .record_host_to_device(len.saturating_mul(std::mem::size_of::<f32>()));
            Ok(())
        }

        pub fn upload_f32_from_pinned_range(
            &self,
            source: &CudaPinnedF32Buffer,
            source_offset: usize,
            destination: &mut CudaF32Buffer,
        ) -> Result<()> {
            let source_end = source_offset
                .checked_add(destination.len())
                .ok_or_else(|| {
                    XrtError::Runtime("pinned f32 upload range overflowed".to_string())
                })?;
            if source_end > source.len() {
                return Err(XrtError::Shape(format!(
                    "pinned f32 upload range {source_offset}..{source_end} exceeds source length {}",
                    source.len()
                )));
            }
            if destination.is_empty() {
                return Ok(());
            }
            self.device
                .htod_sync_copy_into(
                    &source.as_slice()[source_offset..source_end],
                    &mut destination.data,
                )
                .map_err(|err| {
                    cuda_error("failed to copy pinned f32 values into device buffer", err)
                })?;
            self.transfer_counters
                .record_host_to_device(destination.byte_len());
            Ok(())
        }

        pub fn copy_f32_device(
            &self,
            source: &CudaF32Buffer,
            destination: &mut CudaF32Buffer,
        ) -> Result<()> {
            expect_len(
                destination.len(),
                source.len(),
                "f32 device copy destination",
            )?;
            if source.is_empty() {
                return Ok(());
            }
            self.device
                .dtod_copy(&source.data, &mut destination.data)
                .map_err(|err| cuda_error("failed to copy f32 device buffer", err))?;
            self.transfer_counters
                .record_device_to_device(source.byte_len());
            Ok(())
        }

        pub fn copy_f32_device_into_range(
            &self,
            source: &CudaF32Buffer,
            destination: &mut CudaF32Buffer,
            destination_offset: usize,
        ) -> Result<()> {
            let destination_end = destination_offset
                .checked_add(source.len())
                .ok_or_else(|| XrtError::Cuda("f32 device range copy overflowed".to_string()))?;
            if destination_end > destination.len() {
                return Err(XrtError::Cuda(format!(
                    "f32 device range copy [{destination_offset}..{destination_end}) exceeds destination length {}",
                    destination.len()
                )));
            }
            if source.is_empty() {
                return Ok(());
            }
            let mut destination_view = destination
                .data
                .try_slice_mut(destination_offset..destination_end)
                .ok_or_else(|| {
                    XrtError::Cuda("failed to slice f32 device destination".to_string())
                })?;
            self.device
                .dtod_copy(&source.data, &mut destination_view)
                .map_err(|err| cuda_error("failed to copy f32 device buffer range", err))?;
            self.transfer_counters
                .record_device_to_device(source.byte_len());
            Ok(())
        }

        pub fn copy_f32_device_range(
            &self,
            source: &CudaF32Buffer,
            source_offset: usize,
            destination: &mut CudaF32Buffer,
        ) -> Result<()> {
            let source_end = source_offset
                .checked_add(destination.len())
                .ok_or_else(|| XrtError::Cuda("f32 device source range overflowed".to_string()))?;
            if source_end > source.len() {
                return Err(XrtError::Cuda(format!(
                    "f32 device source range [{source_offset}..{source_end}) exceeds source length {}",
                    source.len()
                )));
            }
            if destination.is_empty() {
                return Ok(());
            }
            let source_view = source
                .data
                .try_slice(source_offset..source_end)
                .ok_or_else(|| XrtError::Cuda("failed to slice f32 device source".to_string()))?;
            self.device
                .dtod_copy(&source_view, &mut destination.data)
                .map_err(|err| cuda_error("failed to copy f32 device source range", err))?;
            self.transfer_counters
                .record_device_to_device(destination.byte_len());
            Ok(())
        }

        pub fn copy_f32_device_subrange(
            &self,
            source: &CudaF32Buffer,
            source_offset: usize,
            destination: &mut CudaF32Buffer,
            destination_offset: usize,
            len: usize,
        ) -> Result<()> {
            let source_end = source_offset.checked_add(len).ok_or_else(|| {
                XrtError::Cuda("f32 device source subrange overflowed".to_string())
            })?;
            let destination_end = destination_offset.checked_add(len).ok_or_else(|| {
                XrtError::Cuda("f32 device destination subrange overflowed".to_string())
            })?;
            if source_end > source.len() || destination_end > destination.len() {
                return Err(XrtError::Cuda(format!(
                    "f32 device subrange source [{source_offset}..{source_end})/{} destination [{destination_offset}..{destination_end})/{}",
                    source.len(),
                    destination.len()
                )));
            }
            if len == 0 {
                return Ok(());
            }
            let source_view = source
                .data
                .try_slice(source_offset..source_end)
                .ok_or_else(|| XrtError::Cuda("failed to slice f32 device source".to_string()))?;
            let mut destination_view = destination
                .data
                .try_slice_mut(destination_offset..destination_end)
                .ok_or_else(|| {
                    XrtError::Cuda("failed to slice f32 device destination".to_string())
                })?;
            self.device
                .dtod_copy(&source_view, &mut destination_view)
                .map_err(|err| cuda_error("failed to copy f32 device subrange", err))?;
            self.transfer_counters
                .record_device_to_device(len.saturating_mul(std::mem::size_of::<f32>()));
            Ok(())
        }

        pub fn download_f32(&self, buffer: &CudaF32Buffer) -> Result<Vec<f32>> {
            let view = buffer
                .data
                .try_slice(..buffer.len)
                .ok_or_else(|| XrtError::Cuda("failed to slice logical f32 buffer".to_string()))?;
            let values = self
                .device
                .dtoh_sync_copy(&view)
                .map_err(|err| cuda_error("failed to copy f32 buffer to host", err))?;
            self.transfer_counters
                .record_device_to_host(buffer.byte_len());
            Ok(values)
        }

        pub fn download_f32_range(
            &self,
            buffer: &CudaF32Buffer,
            offset: usize,
            len: usize,
        ) -> Result<Vec<f32>> {
            let end = offset
                .checked_add(len)
                .ok_or_else(|| XrtError::Cuda("f32 download range overflowed".to_string()))?;
            if end > buffer.len() {
                return Err(XrtError::Cuda(format!(
                    "f32 download range [{offset}..{end}) exceeds buffer length {}",
                    buffer.len()
                )));
            }
            let view = buffer
                .data
                .try_slice(offset..end)
                .ok_or_else(|| XrtError::Cuda("failed to slice f32 download range".to_string()))?;
            let values = self
                .device
                .dtoh_sync_copy(&view)
                .map_err(|err| cuda_error("failed to copy f32 buffer range to host", err))?;
            self.transfer_counters
                .record_device_to_host(len.saturating_mul(std::mem::size_of::<f32>()));
            Ok(values)
        }

        /// Selects the last maximum under Rust's `f32::total_cmp` ordering and
        /// downloads only its exactly representable index.
        pub fn argmax_total_f32_into(
            &self,
            input: &CudaF32Buffer,
            output_index: &mut CudaF32Buffer,
        ) -> Result<u32> {
            self.argmax_total_f32_prefix_into(input, input.len(), output_index)
        }

        pub fn argmax_total_f32_prefix_into(
            &self,
            input: &CudaF32Buffer,
            input_len: usize,
            output_index: &mut CudaF32Buffer,
        ) -> Result<u32> {
            self.argmax_total_f32_prefix_device_into(input, input_len, output_index)?;
            self.download_argmax_total_f32(output_index, input_len)
        }

        /// Launches total-order argmax without synchronizing the result back to
        /// the host. This form is safe to capture inside a CUDA graph.
        pub fn argmax_total_f32_prefix_device_into(
            &self,
            input: &CudaF32Buffer,
            input_len: usize,
            output_index: &mut CudaF32Buffer,
        ) -> Result<()> {
            if input_len == 0 {
                return Err(XrtError::Shape(
                    "CUDA argmax input must not be empty".to_string(),
                ));
            }
            if input_len > input.len() {
                return Err(XrtError::Shape(format!(
                    "CUDA argmax prefix length {input_len} exceeds input length {}",
                    input.len()
                )));
            }
            if output_index.len() < 1 {
                return Err(XrtError::Shape(
                    "CUDA argmax output must contain at least one scalar".to_string(),
                ));
            }
            let len = to_u32(input_len, "CUDA argmax input length")?;
            let func = self.function(self.modules.argmax, "argmax_total_f32_kernel")?;
            unsafe {
                func.launch(
                    argmax_total_f32_launch(),
                    (&input.data, &mut output_index.data, len),
                )
            }
            .map_err(|err| cuda_error("failed to launch f32 total-order argmax kernel", err))?;
            Ok(())
        }

        /// Launches total-order argmax plus a compact confidence reduction.
        /// The output contains `[index, softmax_probability, top_two_gap]` and
        /// remains safe to capture inside a CUDA graph.
        pub fn argmax_total_f32_confidence_prefix_device_into(
            &self,
            input: &CudaF32Buffer,
            input_len: usize,
            output: &mut CudaF32Buffer,
        ) -> Result<()> {
            if input_len == 0 {
                return Err(XrtError::Shape(
                    "CUDA argmax confidence input must not be empty".to_string(),
                ));
            }
            if input_len > input.len() {
                return Err(XrtError::Shape(format!(
                    "CUDA argmax confidence prefix length {input_len} exceeds input length {}",
                    input.len()
                )));
            }
            expect_len(output.len(), 3, "CUDA argmax confidence output")?;
            let len = to_u32(input_len, "CUDA argmax confidence input length")?;
            let func = self.function(self.modules.argmax, "argmax_total_f32_confidence_kernel")?;
            unsafe {
                func.launch(
                    argmax_total_f32_launch(),
                    (&input.data, &mut output.data, len),
                )
            }
            .map_err(|err| cuda_error("failed to launch f32 argmax confidence kernel", err))?;
            Ok(())
        }

        /// Downloads an index produced by `argmax_total_f32_prefix_device_into`.
        pub fn download_argmax_total_f32(
            &self,
            output_index: &CudaF32Buffer,
            input_len: usize,
        ) -> Result<u32> {
            if output_index.len() < 1 {
                return Err(XrtError::Shape(
                    "CUDA argmax output must contain at least one scalar".to_string(),
                ));
            }
            let result = self.download_f32(output_index)?[0];
            if !result.is_finite() || result < 0.0 || result >= input_len as f32 {
                return Err(XrtError::Cuda(format!(
                    "CUDA argmax produced invalid encoded index {result} for {input_len} values"
                )));
            }
            Ok(result as u32)
        }

        /// Downloads `[index, softmax_probability, top_two_gap]` produced by
        /// `argmax_total_f32_confidence_prefix_device_into`.
        pub fn download_argmax_total_f32_confidence(
            &self,
            output: &CudaF32Buffer,
            input_len: usize,
        ) -> Result<(u32, f32, f32)> {
            expect_len(output.len(), 3, "CUDA argmax confidence output")?;
            let values = self.download_f32(output)?;
            let index = values[0];
            let probability = values[1];
            let gap = values[2];
            if !index.is_finite() || index < 0.0 || index >= input_len as f32 {
                return Err(XrtError::Cuda(format!(
                    "CUDA argmax confidence produced invalid encoded index {index} for {input_len} values"
                )));
            }
            if !probability.is_finite() || !(0.0..=1.0).contains(&probability) {
                return Err(XrtError::Cuda(format!(
                    "CUDA argmax confidence produced invalid probability {probability}"
                )));
            }
            if gap.is_nan() || gap < 0.0 {
                return Err(XrtError::Cuda(format!(
                    "CUDA argmax confidence produced invalid top-two gap {gap}"
                )));
            }
            Ok((index as u32, probability, gap))
        }

        /// Selects the first finite maximum independently for every row and
        /// downloads only the exactly representable winning indices.
        pub fn argmax_first_f32_rows_into(
            &self,
            input: &CudaF32Buffer,
            rows: usize,
            columns: usize,
            output_indices: &mut CudaF32Buffer,
        ) -> Result<Vec<u32>> {
            self.argmax_first_f32_rows_device_into(input, rows, columns, output_indices)?;
            self.download_argmax_first_f32_rows(output_indices, columns)
        }

        pub fn argmax_first_f32_rows_device_into(
            &self,
            input: &CudaF32Buffer,
            rows: usize,
            columns: usize,
            output_indices: &mut CudaF32Buffer,
        ) -> Result<()> {
            if rows == 0 || columns == 0 {
                return Err(XrtError::Shape(
                    "CUDA row argmax requires non-zero rows and columns".to_string(),
                ));
            }
            let expected = rows
                .checked_mul(columns)
                .ok_or_else(|| XrtError::Shape("CUDA row argmax shape overflowed".to_string()))?;
            expect_len(input.len(), expected, "CUDA row argmax input")?;
            expect_len(output_indices.len(), rows, "CUDA row argmax output")?;
            let rows_u32 = to_u32(rows, "CUDA row argmax rows")?;
            let columns_u32 = to_u32(columns, "CUDA row argmax columns")?;
            let func = self.function(self.modules.argmax, "argmax_first_f32_rows_kernel")?;
            unsafe {
                func.launch(
                    LaunchConfig {
                        grid_dim: (rows_u32, 1, 1),
                        block_dim: (256, 1, 1),
                        shared_mem_bytes: 0,
                    },
                    (&input.data, &mut output_indices.data, rows_u32, columns_u32),
                )
            }
            .map_err(|err| cuda_error("failed to launch f32 row argmax kernel", err))?;
            Ok(())
        }

        pub fn argmax_first_f16_rows_device_into(
            &self,
            input: &CudaBytes,
            rows: usize,
            columns: usize,
            output_indices: &mut CudaF32Buffer,
        ) -> Result<()> {
            if rows == 0 || columns == 0 {
                return Err(XrtError::Shape(
                    "CUDA F16 row argmax requires non-zero rows and columns".to_string(),
                ));
            }
            let expected_bytes = rows
                .checked_mul(columns)
                .and_then(|elements| elements.checked_mul(2))
                .ok_or_else(|| {
                    XrtError::Shape("CUDA F16 row argmax shape overflowed".to_string())
                })?;
            if input.len() < expected_bytes {
                return Err(XrtError::Shape(format!(
                    "CUDA F16 row argmax input has {} bytes but requires at least {expected_bytes}",
                    input.len()
                )));
            }
            if output_indices.len() < rows {
                return Err(XrtError::Shape(format!(
                    "CUDA F16 row argmax output requires at least {rows} elements, found {}",
                    output_indices.len()
                )));
            }
            let rows_u32 = to_u32(rows, "CUDA F16 row argmax rows")?;
            let columns_u32 = to_u32(columns, "CUDA F16 row argmax columns")?;
            let func = self.function(self.modules.argmax, "argmax_first_f16_rows_kernel")?;
            unsafe {
                func.launch(
                    LaunchConfig {
                        grid_dim: (rows_u32, 1, 1),
                        block_dim: (256, 1, 1),
                        shared_mem_bytes: 0,
                    },
                    (&input.data, &mut output_indices.data, rows_u32, columns_u32),
                )
            }
            .map_err(|err| cuda_error("failed to launch f16 row argmax kernel", err))?;
            Ok(())
        }

        /// Selects the first finite maximum from a contiguous row range of a
        /// larger device buffer. This keeps DSpark's Markov-corrected logits
        /// in their resident output-head matrix instead of copying a complete
        /// vocabulary row into a temporary allocation before every argmax.
        pub fn argmax_first_f32_rows_device_subrange_into(
            &self,
            input: &CudaF32Buffer,
            input_offset: usize,
            rows: usize,
            columns: usize,
            output_indices: &mut CudaF32Buffer,
        ) -> Result<()> {
            if rows == 0 || columns == 0 {
                return Err(XrtError::Shape(
                    "CUDA row-subrange argmax requires non-zero rows and columns".to_string(),
                ));
            }
            let len = rows.checked_mul(columns).ok_or_else(|| {
                XrtError::Shape("CUDA row-subrange argmax shape overflowed".to_string())
            })?;
            let input_end = input_offset.checked_add(len).ok_or_else(|| {
                XrtError::Shape("CUDA row-subrange argmax offset overflowed".to_string())
            })?;
            if input_end > input.len() {
                return Err(XrtError::Shape(format!(
                    "CUDA row-subrange argmax [{input_offset}..{input_end}) exceeds input length {}",
                    input.len()
                )));
            }
            expect_len(
                output_indices.len(),
                rows,
                "CUDA row-subrange argmax output",
            )?;
            let input_view = input
                .data
                .try_slice(input_offset..input_end)
                .ok_or_else(|| XrtError::Cuda("failed to slice row-argmax input".to_string()))?;
            let rows_u32 = to_u32(rows, "CUDA row-subrange argmax rows")?;
            let columns_u32 = to_u32(columns, "CUDA row-subrange argmax columns")?;
            let func = self.function(self.modules.argmax, "argmax_first_f32_rows_kernel")?;
            unsafe {
                func.launch(
                    LaunchConfig {
                        grid_dim: (rows_u32, 1, 1),
                        block_dim: (256, 1, 1),
                        shared_mem_bytes: 0,
                    },
                    (&input_view, &mut output_indices.data, rows_u32, columns_u32),
                )
            }
            .map_err(|err| cuda_error("failed to launch f32 row-subrange argmax kernel", err))?;
            Ok(())
        }

        pub fn download_argmax_first_f32_rows(
            &self,
            output_indices: &CudaF32Buffer,
            columns: usize,
        ) -> Result<Vec<u32>> {
            let columns_u32 = to_u32(columns, "CUDA row argmax columns")?;
            self.download_f32(output_indices)?
                .into_iter()
                .map(|encoded| {
                    if !encoded.is_finite()
                        || encoded < 0.0
                        || encoded > u32::MAX as f32
                        || encoded >= columns_u32 as f32
                    {
                        return Err(XrtError::Cuda(format!(
                            "CUDA row argmax produced invalid encoded index {encoded}"
                        )));
                    }
                    Ok(encoded as u32)
                })
                .collect()
        }

        /// Maps one exactly encoded device-resident f32 index through a
        /// device-resident f32 table. Every supported token ID is exactly
        /// representable and can feed the existing device-token embedding
        /// kernels directly.
        pub fn lookup_f32_table_device_index_into(
            &self,
            table: &CudaF32Buffer,
            table_len: usize,
            encoded_index: &CudaF32Buffer,
            output: &mut CudaF32Buffer,
        ) -> Result<()> {
            if table_len == 0 || table_len > table.len() {
                return Err(XrtError::Shape(format!(
                    "CUDA f32 lookup table length {table_len} is invalid for buffer length {}",
                    table.len()
                )));
            }
            if encoded_index.len() < 1 || output.len() < 1 {
                return Err(XrtError::Shape(
                    "CUDA f32 lookup requires one encoded index and one output scalar".to_string(),
                ));
            }
            let table_len = to_u32(table_len, "CUDA f32 lookup table length")?;
            let func =
                self.function(self.modules.argmax, "lookup_f32_table_device_index_kernel")?;
            unsafe {
                func.launch(
                    LaunchConfig {
                        grid_dim: (1, 1, 1),
                        block_dim: (1, 1, 1),
                        shared_mem_bytes: 0,
                    },
                    (
                        &table.data,
                        &encoded_index.data,
                        &mut output.data,
                        table_len,
                    ),
                )
            }
            .map_err(|err| cuda_error("failed to launch f32 table lookup kernel", err))
        }

        /// Selects the first four finite maxima in every row and returns each
        /// token ID with its full-vocabulary log-softmax score. The compact
        /// output is ordered best-first within every row.
        pub fn top4_first_f32_rows_into(
            &self,
            input: &CudaF32Buffer,
            rows: usize,
            columns: usize,
            output: &mut CudaF32Buffer,
        ) -> Result<Vec<[(u32, f32); 4]>> {
            if rows == 0 || columns < 4 {
                return Err(XrtError::Shape(format!(
                    "CUDA row top-4 requires non-zero rows and at least four columns, found {rows}x{columns}"
                )));
            }
            let expected = rows
                .checked_mul(columns)
                .ok_or_else(|| XrtError::Shape("CUDA row top-4 shape overflowed".to_string()))?;
            expect_len(input.len(), expected, "CUDA row top-4 input")?;
            let output_len = rows
                .checked_mul(8)
                .ok_or_else(|| XrtError::Shape("CUDA row top-4 output overflowed".to_string()))?;
            expect_len(output.len(), output_len, "CUDA row top-4 output")?;
            let rows_u32 = to_u32(rows, "CUDA row top-4 rows")?;
            let columns_u32 = to_u32(columns, "CUDA row top-4 columns")?;
            let func = self.function(self.modules.argmax, "top4_first_f32_rows_kernel")?;
            unsafe {
                func.launch(
                    LaunchConfig {
                        grid_dim: (rows_u32, 1, 1),
                        block_dim: (256, 1, 1),
                        shared_mem_bytes: 0,
                    },
                    (&input.data, &mut output.data, rows_u32, columns_u32),
                )
            }
            .map_err(|err| cuda_error("failed to launch f32 row top-4 kernel", err))?;

            let encoded = self.download_f32(output)?;
            encoded
                .chunks_exact(8)
                .map(|row| {
                    let mut result = [(0u32, f32::NEG_INFINITY); 4];
                    for slot in 0..4 {
                        let index = row[slot * 2];
                        let log_probability = row[slot * 2 + 1];
                        if !index.is_finite()
                            || index < 0.0
                            || index >= columns_u32 as f32
                            || !log_probability.is_finite()
                            || log_probability > 1e-5
                        {
                            return Err(XrtError::Cuda(format!(
                                "CUDA row top-4 produced invalid slot {slot}: index={index}, log_probability={log_probability}"
                            )));
                        }
                        result[slot] = (index as u32, log_probability);
                    }
                    Ok(result)
                })
                .collect()
        }

        pub fn download_f32_into_pinned(
            &self,
            buffer: &CudaF32Buffer,
            destination: &mut CudaPinnedF32Buffer,
        ) -> Result<()> {
            expect_len(
                destination.len(),
                buffer.len(),
                "pinned f32 download destination",
            )?;
            if buffer.is_empty() {
                return Ok(());
            }
            self.device
                .dtoh_sync_copy_into(&buffer.data, destination.as_mut_slice())
                .map_err(|err| {
                    cuda_error("failed to copy device f32 values into pinned staging", err)
                })?;
            self.transfer_counters
                .record_device_to_host(buffer.byte_len());
            Ok(())
        }

        /// Enqueue a device-to-host copy into an owned pinned allocation and
        /// record a completion event on the supplied nonblocking stream.
        ///
        /// # Safety
        ///
        /// `buffer` must outlive the returned transfer and must not be freed or
        /// repurposed until `CudaPinnedF32Download::wait` (or Drop) completes.
        pub unsafe fn download_f32_into_pinned_async(
            &self,
            buffer: &CudaF32Buffer,
            mut destination: CudaPinnedF32Buffer,
            stream: CudaExecutionStream,
        ) -> Result<CudaPinnedF32Download> {
            expect_len(
                destination.len(),
                buffer.len(),
                "async pinned f32 download destination",
            )?;
            if !Arc::ptr_eq(&self.device, &destination.device)
                || !Arc::ptr_eq(&self.device, &stream.device)
            {
                return Err(XrtError::Cuda(
                    "CUDA async pinned download resources belong to different devices".to_string(),
                ));
            }
            if buffer.is_empty() {
                return Ok(CudaPinnedF32Download {
                    device: Arc::clone(&self.device),
                    buffer: Some(destination),
                    stream: Some(stream),
                    event: ptr::null_mut(),
                    complete: true,
                });
            }
            self.device
                .bind_to_thread()
                .map_err(|err| cuda_error("failed to bind CUDA async transfer context", err))?;
            let event = driver_result::event::create(sys::CUevent_flags::CU_EVENT_DISABLE_TIMING)
                .map_err(|err| cuda_error("failed to create CUDA transfer event", err))?;
            if let Err(error) = driver_result::memcpy_dtoh_async(
                destination.as_mut_slice(),
                *buffer.data.device_ptr(),
                stream.stream.stream,
            ) {
                let _ = driver_result::event::destroy(event);
                return Err(cuda_error(
                    "failed to enqueue pinned f32 device-to-host copy",
                    error,
                ));
            }
            if let Err(error) = driver_result::event::record(event, stream.stream.stream) {
                let synchronized = driver_result::stream::synchronize(stream.stream.stream);
                let _ = driver_result::event::destroy(event);
                if synchronized.is_err() {
                    std::mem::forget(destination);
                }
                return Err(cuda_error(
                    "failed to record pinned f32 transfer event",
                    error,
                ));
            }
            self.transfer_counters
                .record_device_to_host(buffer.byte_len());
            Ok(CudaPinnedF32Download {
                device: Arc::clone(&self.device),
                buffer: Some(destination),
                stream: Some(stream),
                event,
                complete: false,
            })
        }

        pub fn zero_f32(&self, buffer: &mut CudaF32Buffer) -> Result<()> {
            if buffer.is_empty() {
                return Ok(());
            }
            self.device
                .memset_zeros(&mut buffer.data)
                .map_err(|err| cuda_error("failed to zero CUDA f32 buffer", err))
        }

        pub fn zeros_f32(&self, len: usize) -> Result<CudaF32Buffer> {
            let data = self
                .device
                .alloc_zeros::<f32>(len)
                .map_err(|err| {
                    let requested_bytes = len.saturating_mul(std::mem::size_of::<f32>());
                    let memory = driver_result::mem_get_info()
                        .ok()
                        .map(|(free, total)| format!(", free_bytes={free}, total_bytes={total}"))
                        .unwrap_or_default();
                    cuda_error(
                        &format!(
                            "failed to allocate f32 buffer on device (elements={len}, requested_bytes={requested_bytes}{memory})"
                        ),
                        err,
                    )
                })?;
            let allocation = self.track_allocation(len.saturating_mul(std::mem::size_of::<f32>()));
            Ok(CudaF32Buffer {
                data,
                len,
                capacity_len: len,
                _allocation: allocation,
            })
        }

        pub fn zeros_bytes(&self, len: usize) -> Result<CudaBytes> {
            let data = self
                .device
                .alloc_zeros::<u8>(len)
                .map_err(|err| cuda_error("failed to allocate byte buffer on device", err))?;
            let allocation = self.track_allocation(len);
            Ok(CudaBytes {
                data,
                len,
                capacity_len: len,
                _allocation: allocation,
            })
        }

        fn with_kquant_workspace<T>(
            &self,
            required_bytes: usize,
            operation: impl FnOnce(&mut CudaBytes) -> Result<T>,
        ) -> Result<T> {
            let mut workspace = {
                let mut slot = self.kquant_workspace.lock().map_err(|_| {
                    XrtError::Runtime("CUDA K-quant workspace lock was poisoned".to_string())
                })?;
                slot.take()
            };
            if workspace
                .as_ref()
                .map_or(true, |buffer| buffer.byte_len() < required_bytes)
            {
                workspace = Some(self.zeros_bytes(required_bytes)?);
            }
            let mut workspace = workspace.expect("K-quant workspace allocation must be present");
            let result = operation(&mut workspace);

            let recycle_result = self.kquant_workspace.lock().map(|mut slot| {
                let replace = slot
                    .as_ref()
                    .map_or(true, |current| current.byte_len() < workspace.byte_len());
                if replace {
                    *slot = Some(workspace);
                }
            });
            match (result, recycle_result) {
                (Ok(value), Ok(())) => Ok(value),
                (Err(error), _) => Err(error),
                (Ok(_), Err(_)) => Err(XrtError::Runtime(
                    "CUDA K-quant workspace lock was poisoned while recycling".to_string(),
                )),
            }
        }

        fn quantize_q8_mmq_into(
            &self,
            input: &CudaF32Buffer,
            workspace: &mut CudaBytes,
            quant_count: usize,
            quant_blocks: usize,
        ) -> Result<()> {
            expect_len(input.len(), quant_count, "K-quant MMQ activation input")?;
            let quant_count_u32 = to_u32(quant_count, "K-quant MMQ activation elements")?;
            let quant_blocks_u32 = to_u32(quant_blocks, "K-quant MMQ activation blocks")?;
            let func = self.function(self.modules.kquant_mmq, "xrt_quantize_q8_mmq")?;
            unsafe {
                func.launch(
                    q8_mmq_quantize_launch(quant_blocks_u32),
                    (
                        &input.data,
                        &mut workspace.data,
                        quant_count_u32,
                        quant_blocks_u32,
                    ),
                )
            }
            .map_err(|err| cuda_error("failed to launch Q8 MMQ activation quantization", err))?;
            Ok(())
        }

        pub fn alloc_adaptive_kv_routes(&self, capacity: usize) -> Result<CudaAdaptiveKvRoutes> {
            let data = self
                .device
                .alloc_zeros::<u32>(capacity)
                .map_err(|err| cuda_error("failed to allocate CUDA adaptive KV routes", err))?;
            let allocation =
                self.track_allocation(capacity.saturating_mul(std::mem::size_of::<u32>()));
            Ok(CudaAdaptiveKvRoutes {
                data,
                _allocation: allocation,
                capacity,
                len: 0,
            })
        }

        pub fn grow_adaptive_kv_routes(
            &self,
            routes: &mut CudaAdaptiveKvRoutes,
            new_capacity: usize,
        ) -> Result<()> {
            if new_capacity < routes.capacity {
                return Err(XrtError::Runtime(format!(
                    "cannot shrink CUDA adaptive KV route capacity from {} to {new_capacity}",
                    routes.capacity
                )));
            }
            if new_capacity == routes.capacity {
                return Ok(());
            }
            let mut grown = self.alloc_adaptive_kv_routes(new_capacity)?;
            self.copy_page_table_prefix(
                &routes.data,
                &mut grown.data,
                routes.len,
                "CUDA adaptive KV routes",
            )?;
            self.device.synchronize().map_err(|err| {
                cuda_error("failed to synchronize CUDA adaptive KV route growth", err)
            })?;
            grown.len = routes.len;
            *routes = grown;
            Ok(())
        }

        pub fn replace_adaptive_kv_routes(
            &self,
            routes: &mut CudaAdaptiveKvRoutes,
            hot_mask: &[u8],
        ) -> Result<()> {
            if hot_mask.len() > routes.capacity {
                return Err(XrtError::Runtime(format!(
                    "CUDA adaptive KV route length {} exceeds capacity {}",
                    hot_mask.len(),
                    routes.capacity
                )));
            }
            let mut hot_position = 0usize;
            let mut cold_position = 0usize;
            let mut encoded = Vec::with_capacity(hot_mask.len());
            for &is_hot in hot_mask {
                let local_position = if is_hot == 0 {
                    let position = cold_position;
                    cold_position += 1;
                    position
                } else {
                    let position = hot_position;
                    hot_position += 1;
                    position
                };
                encoded.push(encode_adaptive_kv_route(is_hot != 0, local_position)?);
            }
            if !encoded.is_empty() {
                let mut destination =
                    routes.data.try_slice_mut(..encoded.len()).ok_or_else(|| {
                        XrtError::Runtime(
                            "failed to create CUDA adaptive KV route destination view".to_string(),
                        )
                    })?;
                self.device
                    .htod_sync_copy_into(&encoded, &mut destination)
                    .map_err(|err| cuda_error("failed to replace CUDA adaptive KV routes", err))?;
                self.transfer_counters
                    .record_host_to_device(std::mem::size_of_val(encoded.as_slice()));
            }
            routes.len = encoded.len();
            Ok(())
        }

        pub fn append_adaptive_kv_route(
            &self,
            routes: &mut CudaAdaptiveKvRoutes,
            is_hot: bool,
            local_position: usize,
        ) -> Result<()> {
            if routes.len >= routes.capacity {
                return Err(XrtError::Runtime(format!(
                    "CUDA adaptive KV routes are full: len={}, capacity={}",
                    routes.len, routes.capacity
                )));
            }
            let index = to_u32(routes.len, "CUDA adaptive KV route index")?;
            let encoded = encode_adaptive_kv_route(is_hot, local_position)?;
            let func = self.function(self.modules.attention, "adaptive_kv_route_write_kernel")?;
            unsafe {
                func.launch(
                    one_dim_launch(1),
                    (&mut routes.data, index, encoded, 0u32, 0u64),
                )
            }
            .map_err(|err| cuda_error("failed to append CUDA adaptive KV route", err))?;
            routes.len += 1;
            Ok(())
        }

        pub fn alloc_layer_kv_cache(
            &self,
            capacity: usize,
            width: usize,
        ) -> Result<CudaLayerKvCache> {
            self.alloc_paged_layer_kv_cache(capacity, width, capacity.max(1))
        }

        pub fn alloc_paged_layer_kv_cache(
            &self,
            capacity: usize,
            width: usize,
            page_tokens: usize,
        ) -> Result<CudaLayerKvCache> {
            let elements = checked_mul(capacity, width, "CUDA paged KV cache elements")?;
            let (page_table, page_table_allocation, page_tokens, page_count) =
                self.alloc_identity_page_table(capacity, page_tokens, "CUDA F32 KV")?;
            Ok(CudaLayerKvCache {
                storage: CudaF32KvStorage::Contiguous {
                    keys: self.zeros_f32(elements)?,
                    values: self.zeros_f32(elements)?,
                    page_table,
                },
                _metadata_allocation: page_table_allocation,
                capacity,
                len: 0,
                width,
                page_tokens,
                page_count,
            })
        }

        pub fn alloc_shared_paged_layer_kv_cache(
            &self,
            capacity: usize,
            width: usize,
            page_tokens: usize,
        ) -> Result<CudaLayerKvCache> {
            let page_tokens = page_tokens.max(1);
            let page_count = capacity.div_ceil(page_tokens);
            let page_elements =
                checked_mul(page_tokens, width, "CUDA shared F32 KV page elements")?;
            let mut pages = Vec::with_capacity(page_count);
            for _ in 0..page_count {
                pages.push(Arc::new(CudaCowF32KvPage {
                    keys: self.zeros_f32(page_elements)?,
                    values: self.zeros_f32(page_elements)?,
                }));
            }
            let logical_to_physical = (0..page_count).collect::<Vec<_>>();
            let (key_page_pointers, value_page_pointers) =
                self.upload_shared_f32_page_pointers(&pages, &logical_to_physical)?;
            Ok(CudaLayerKvCache {
                storage: CudaF32KvStorage::SharedPages {
                    pages,
                    logical_to_physical,
                    key_page_pointers,
                    value_page_pointers,
                },
                _metadata_allocation: self.track_allocation(
                    page_count
                        .saturating_mul(2)
                        .saturating_mul(std::mem::size_of::<u64>()),
                ),
                capacity,
                len: 0,
                width,
                page_tokens,
                page_count,
            })
        }

        pub fn remap_paged_layer_kv_pages(
            &self,
            cache: &mut CudaLayerKvCache,
            page_map: &[u32],
        ) -> Result<()> {
            Self::validate_page_map(
                cache.capacity,
                cache.page_tokens,
                cache.page_count,
                page_map,
                "CUDA F32 KV",
            )?;
            match &mut cache.storage {
                CudaF32KvStorage::Contiguous { page_table, .. } => {
                    self.upload_page_map(page_table, page_map, "CUDA F32 KV")
                }
                CudaF32KvStorage::SharedPages {
                    pages,
                    logical_to_physical,
                    key_page_pointers,
                    value_page_pointers,
                } => {
                    *logical_to_physical = page_map
                        .iter()
                        .map(|&page| usize::try_from(page).unwrap_or(usize::MAX))
                        .collect();
                    self.refresh_shared_f32_page_pointers(
                        pages,
                        logical_to_physical,
                        key_page_pointers,
                        value_page_pointers,
                    )
                }
            }
        }

        pub fn alloc_q8_layer_kv_cache(
            &self,
            capacity: usize,
            width: usize,
        ) -> Result<CudaQ8LayerKvCache> {
            self.alloc_paged_q8_layer_kv_cache(capacity, width, capacity.max(1))
        }

