        pub fn append_layer_kv(
            &self,
            cache: &mut CudaLayerKvCache,
            key: &CudaF32Buffer,
            value: &CudaF32Buffer,
        ) -> Result<()> {
            expect_len(key.len(), cache.width, "CUDA KV key")?;
            expect_len(value.len(), cache.width, "CUDA KV value")?;
            if cache.len >= cache.capacity {
                return Err(XrtError::Runtime(format!(
                    "CUDA KV cache is full: len={}, capacity={}",
                    cache.len, cache.capacity
                )));
            }
            if cache.width == 0 {
                cache.len += 1;
                return Ok(());
            }

            let slot_u32 = to_u32(cache.len, "CUDA KV slot")?;
            let width_u32 = to_u32(cache.width, "CUDA KV width")?;
            let page_tokens_u32 = to_u32(cache.page_tokens, "CUDA KV page tokens")?;
            match &mut cache.storage {
                CudaF32KvStorage::Contiguous {
                    keys,
                    values,
                    page_table,
                } => {
                    let func =
                        self.function(self.modules.attention, "paged_kv_cache_append_kernel")?;
                    unsafe {
                        func.launch(
                            one_dim_launch(width_u32),
                            (
                                &mut keys.data,
                                &mut values.data,
                                page_table,
                                &key.data,
                                &value.data,
                                slot_u32,
                                width_u32,
                                page_tokens_u32,
                                0u64,
                            ),
                        )
                    }
                    .map_err(|err| {
                        cuda_error("failed to launch paged KV cache append kernel", err)
                    })?;
                }
                CudaF32KvStorage::SharedPages {
                    pages,
                    logical_to_physical,
                    key_page_pointers,
                    value_page_pointers,
                } => {
                    let logical_page = cache.len / cache.page_tokens;
                    let physical_page = logical_to_physical[logical_page];
                    if Arc::strong_count(&pages[physical_page]) != 1 {
                        return Err(XrtError::Runtime(format!(
                            "CUDA shared F32 KV page {logical_page} is immutable; prepare copy-on-write before append"
                        )));
                    }
                    let func =
                        self.function(self.modules.shared_f32_kv, "shared_f32_kv_append_kernel")?;
                    unsafe {
                        func.launch(
                            one_dim_launch(width_u32),
                            (
                                key_page_pointers,
                                value_page_pointers,
                                &key.data,
                                &value.data,
                                slot_u32,
                                width_u32,
                                page_tokens_u32,
                                0u64,
                            ),
                        )
                    }
                    .map_err(|err| {
                        cuda_error("failed to launch shared F32 KV append kernel", err)
                    })?;
                }
            }
            cache.len += 1;
            Ok(())
        }

        pub fn append_layer_kv_with_decode_params(
            &self,
            cache: &mut CudaLayerKvCache,
            key: &CudaF32Buffer,
            value: &CudaF32Buffer,
            params: &CudaDecodeParams,
        ) -> Result<()> {
            expect_len(key.len(), cache.width, "CUDA graph KV key")?;
            expect_len(value.len(), cache.width, "CUDA graph KV value")?;
            expect_len(
                cache.capacity,
                params.capacity,
                "CUDA graph KV parameter capacity",
            )?;
            if cache.width == 0 {
                return Ok(());
            }

            let width_u32 = to_u32(cache.width, "CUDA graph KV width")?;
            let page_tokens_u32 = to_u32(cache.page_tokens, "CUDA graph KV page tokens")?;
            match &mut cache.storage {
                CudaF32KvStorage::Contiguous {
                    keys,
                    values,
                    page_table,
                } => {
                    let func =
                        self.function(self.modules.attention, "paged_kv_cache_append_kernel")?;
                    unsafe {
                        func.launch(
                            one_dim_launch(width_u32),
                            (
                                &mut keys.data,
                                &mut values.data,
                                page_table,
                                &key.data,
                                &value.data,
                                0u32,
                                width_u32,
                                page_tokens_u32,
                                &params.data,
                            ),
                        )
                    }
                    .map_err(|err| cuda_error("failed to launch graph-aware paged KV append", err))
                }
                CudaF32KvStorage::SharedPages {
                    key_page_pointers,
                    value_page_pointers,
                    ..
                } => {
                    let func =
                        self.function(self.modules.shared_f32_kv, "shared_f32_kv_append_kernel")?;
                    unsafe {
                        func.launch(
                            one_dim_launch(width_u32),
                            (
                                key_page_pointers,
                                value_page_pointers,
                                &key.data,
                                &value.data,
                                0u32,
                                width_u32,
                                page_tokens_u32,
                                &params.data,
                            ),
                        )
                    }
                    .map_err(|err| {
                        cuda_error("failed to launch graph-aware shared F32 KV append", err)
                    })
                }
            }
        }

        pub fn commit_layer_kv_graph_append(
            &self,
            cache: &mut CudaLayerKvCache,
            position: usize,
        ) -> Result<()> {
            if cache.len != position {
                return Err(XrtError::Runtime(format!(
                    "CUDA graph KV commit expected cache len {position}, found {}",
                    cache.len
                )));
            }
            if cache.len >= cache.capacity {
                return Err(XrtError::Runtime(format!(
                    "CUDA graph KV cache is full: len={}, capacity={}",
                    cache.len, cache.capacity
                )));
            }
            cache.len += 1;
            Ok(())
        }

        pub fn commit_layer_kv_graph_append_batch(
            &self,
            cache: &mut CudaLayerKvCache,
            start_position: usize,
            rows: usize,
        ) -> Result<()> {
            if cache.len != start_position {
                return Err(XrtError::Runtime(format!(
                    "CUDA graph KV batch commit expected cache len {start_position}, found {}",
                    cache.len
                )));
            }
            let end_position = start_position.checked_add(rows).ok_or_else(|| {
                XrtError::Runtime("CUDA graph KV batch commit overflowed".to_string())
            })?;
            if end_position > cache.capacity {
                return Err(XrtError::Runtime(format!(
                    "CUDA graph KV batch commit end {end_position} exceeds capacity {}",
                    cache.capacity
                )));
            }
            cache.len = end_position;
            Ok(())
        }

        pub fn gather_paged_layer_kv(
            &self,
            cache: &CudaLayerKvCache,
            start_position: usize,
            count: usize,
        ) -> Result<(CudaF32Buffer, CudaF32Buffer)> {
            let end = start_position.checked_add(count).ok_or_else(|| {
                XrtError::Runtime("CUDA paged KV gather range overflow".to_string())
            })?;
            if end > cache.len {
                return Err(XrtError::Runtime(format!(
                    "CUDA paged KV gather range {start_position}..{end} exceeds cache length {}",
                    cache.len
                )));
            }
            let elements = checked_mul(count, cache.width, "CUDA paged KV gather elements")?;
            let mut keys = self.zeros_f32(elements)?;
            let mut values = self.zeros_f32(elements)?;
            if elements == 0 {
                return Ok((keys, values));
            }

            let launch = one_dim_launch(to_u32(elements, "CUDA paged KV gather elements")?);
            let count = to_u32(count, "CUDA paged KV gather count")?;
            let width = to_u32(cache.width, "CUDA paged KV gather width")?;
            let page_tokens = to_u32(cache.page_tokens, "CUDA paged KV gather page tokens")?;
            let start_position = to_u32(start_position, "CUDA paged KV gather start position")?;
            match &cache.storage {
                CudaF32KvStorage::Contiguous {
                    keys: cache_keys,
                    values: cache_values,
                    page_table,
                } => {
                    let func =
                        self.function(self.modules.attention, "paged_kv_cache_gather_kernel")?;
                    unsafe {
                        func.launch(
                            launch,
                            (
                                &cache_keys.data,
                                &cache_values.data,
                                page_table,
                                &mut keys.data,
                                &mut values.data,
                                count,
                                width,
                                page_tokens,
                                start_position,
                            ),
                        )
                    }
                    .map_err(|err| cuda_error("failed to launch paged KV gather kernel", err))?;
                }
                CudaF32KvStorage::SharedPages {
                    key_page_pointers,
                    value_page_pointers,
                    ..
                } => {
                    let func =
                        self.function(self.modules.shared_f32_kv, "shared_f32_kv_gather_kernel")?;
                    unsafe {
                        func.launch(
                            launch,
                            (
                                key_page_pointers,
                                value_page_pointers,
                                &mut keys.data,
                                &mut values.data,
                                count,
                                width,
                                page_tokens,
                                start_position,
                            ),
                        )
                    }
                    .map_err(|err| {
                        cuda_error("failed to launch shared F32 KV gather kernel", err)
                    })?;
                }
            }
            Ok((keys, values))
        }

        pub fn copy_layer_kv(
            &self,
            cache: &CudaLayerKvCache,
            position: usize,
        ) -> Result<(CudaF32Buffer, CudaF32Buffer)> {
            self.gather_paged_layer_kv(cache, position, 1)
        }

        pub fn append_q8_layer_kv(
            &self,
            cache: &mut CudaQ8LayerKvCache,
            key: &CudaF32Buffer,
            value: &CudaF32Buffer,
        ) -> Result<()> {
            expect_len(key.len(), cache.width, "CUDA Q8 KV key")?;
            expect_len(value.len(), cache.width, "CUDA Q8 KV value")?;
            if cache.len >= cache.capacity {
                return Err(XrtError::Runtime(format!(
                    "CUDA Q8 KV cache is full: len={}, capacity={}",
                    cache.len, cache.capacity
                )));
            }
            if cache.width == 0 {
                cache.len += 1;
                return Ok(());
            }

            let slot_u32 = to_u32(cache.len, "CUDA Q8 KV slot")?;
            let width_u32 = to_u32(cache.width, "CUDA Q8 KV width")?;
            let page_tokens_u32 = to_u32(cache.page_tokens, "CUDA Q8 KV page tokens")?;
            let func = self.function(self.modules.attention, "q8_kv_cache_append_kernel")?;
            unsafe {
                func.launch(
                    one_dim_launch(1),
                    (
                        &mut cache.keys.data,
                        &mut cache.values.data,
                        &mut cache.key_scales.data,
                        &mut cache.value_scales.data,
                        &key.data,
                        &value.data,
                        slot_u32,
                        width_u32,
                        &cache.page_table,
                        page_tokens_u32,
                        0u64,
                    ),
                )
            }
            .map_err(|err| cuda_error("failed to launch Q8 KV cache append kernel", err))?;
            cache.len += 1;
            Ok(())
        }

