        pub(crate) fn upload_q6_k_matrix_packed_with_marlin(
            &self,
            matrix: &[u8],
            rows: usize,
            cols: usize,
            allow_marlin: bool,
        ) -> Result<CudaQ6KMatrix> {
            if allow_marlin && rows % 64 == 0 && cols % 256 == 0 {
                return Ok(CudaQ4KMatrix {
                    storage: CudaKQuantMatrixStorage::Q6KMarlin {
                        matrix: Box::new(self.upload_q6_k_marlin_matrix(matrix, rows, cols)?),
                    },
                    rows,
                    cols,
                });
            }
            let d = q6_k_block_scales(matrix, rows, cols)?;
            let verify_input_f16 = if self.q6_k_f16_verify_input_enabled {
                Some(Mutex::new(self.zeros_bytes(checked_mul(
                    checked_mul(16, cols, "Q6_K F16 verify scratch elements")?,
                    2,
                    "Q6_K F16 verify scratch bytes",
                )?)?))
            } else {
                None
            };
            Ok(CudaQ4KMatrix {
                storage: CudaKQuantMatrixStorage::Q6K {
                    d: self.upload_f32(&d)?,
                    blocks: self.upload_bytes(matrix)?,
                    verify_input_f16,
                },
                rows,
                cols,
            })
        }

        pub fn upload_q6_k_embedding_matrix_packed(
            &self,
            matrix: &[u8],
            rows: usize,
            cols: usize,
        ) -> Result<CudaQ6KMatrix> {
            // Marlin packs weights for GEMM; an embedding table is gathered by
            // row and cannot be read from that layout. Models with tied
            // embeddings reach this path for the same tensor that also serves
            // as the output projection, so the embedding copy must stay
            // row-major even when Marlin is enabled for matmuls. The Q4_K
            // embedding path already does this via upload_q4_k_matrix_raw;
            // Q6_K previously inherited the Marlin branch and produced a table
            // that every embedding kernel then refused.
            self.upload_q6_k_matrix_packed_with_marlin(matrix, rows, cols, false)
        }

        fn upload_q6_k_matrix_with_embedding_rows(
            &self,
            matrix: &[u8],
            rows: usize,
            cols: usize,
            include_row_major: bool,
        ) -> Result<CudaQ6KMatrix> {
            // ponytail: packed Q6_K regressed VibeThinker; dequantize once until a faster kernel exists.
            let values_transposed = dequantize_q6_k_matrix_transposed(matrix, rows, cols)?;
            let values_row_major = if include_row_major {
                Some(transpose_row_major(&values_transposed, rows, cols)?)
            } else {
                None
            };
            Ok(CudaQ4KMatrix {
                storage: CudaKQuantMatrixStorage::ExpandedF32 {
                    values_transposed: self.upload_f32(&values_transposed)?,
                    values_row_major: values_row_major
                        .as_deref()
                        .map(|values| self.upload_f32(values))
                        .transpose()?,
                },
                rows,
                cols,
            })
        }

        pub fn upload_q6_k_tensor(&self, gguf: &GgufFile, name: &str) -> Result<CudaQ6KMatrix> {
            let info = gguf.require_tensor(name)?;
            if info.dtype != DType::Q6_K {
                return Err(XrtError::Unsupported(format!(
                    "resident Q6_K tensor upload requires Q6_K dtype, tensor `{name}` is {:?}",
                    info.dtype
                )));
            }
            self.upload_q6_k_matrix(gguf.tensor_data(name)?, info.rows(), info.row_len())
        }

