        pub fn rmsnorm(
            &self,
            input: &[f32],
            weight: &[f32],
            rows: usize,
            cols: usize,
            eps: f32,
        ) -> Result<Vec<f32>> {
            let expected = checked_mul(rows, cols, "rmsnorm elements")?;
            expect_len(input.len(), expected, "rmsnorm input")?;
            expect_len(weight.len(), cols, "rmsnorm weight")?;
            if expected == 0 {
                return Ok(Vec::new());
            }

            let rows_u32 = to_u32(rows, "rmsnorm rows")?;
            let cols_u32 = to_u32(cols, "rmsnorm cols")?;
            let input_dev = self.upload_f32(input)?;
            let weight_dev = self.upload_f32(weight)?;
            let mut output_dev = self.zeros_f32(expected)?;

            let func = self.function(self.modules.rmsnorm, "rmsnorm_kernel")?;
            unsafe {
                func.launch(
                    row_launch(rows_u32),
                    (
                        &input_dev.data,
                        &weight_dev.data,
                        &mut output_dev.data,
                        rows_u32,
                        cols_u32,
                        eps,
                    ),
                )
            }
            .map_err(|err| cuda_error("failed to launch rmsnorm kernel", err))?;

            self.download_f32(&output_dev)
        }

        pub fn rmsnorm_resident_weight(
            &self,
            input: &[f32],
            weight: &CudaF32Buffer,
            rows: usize,
            cols: usize,
            eps: f32,
        ) -> Result<Vec<f32>> {
            let input = self.upload_f32(input)?;
            self.rmsnorm_device(&input, weight, rows, cols, eps)
                .and_then(|output| self.download_f32(&output))
        }

        pub fn rmsnorm_device(
            &self,
            input: &CudaF32Buffer,
            weight: &CudaF32Buffer,
            rows: usize,
            cols: usize,
            eps: f32,
        ) -> Result<CudaF32Buffer> {
            let expected = checked_mul(rows, cols, "rmsnorm elements")?;
            expect_len(input.len(), expected, "rmsnorm input")?;
            expect_len(weight.len(), cols, "rmsnorm resident weight")?;
            if expected == 0 {
                return self.zeros_f32(0);
            }

            let mut output = self.zeros_f32(expected)?;
            self.rmsnorm_device_into(input, weight, rows, cols, eps, &mut output)?;
            Ok(output)
        }

        pub fn rmsnorm_device_into(
            &self,
            input: &CudaF32Buffer,
            weight: &CudaF32Buffer,
            rows: usize,
            cols: usize,
            eps: f32,
            output: &mut CudaF32Buffer,
        ) -> Result<()> {
            let expected = checked_mul(rows, cols, "rmsnorm elements")?;
            expect_len(input.len(), expected, "rmsnorm input")?;
            expect_len(weight.len(), cols, "rmsnorm resident weight")?;
            expect_len(output.len(), expected, "rmsnorm output")?;
            if expected == 0 {
                return Ok(());
            }

            let rows_u32 = to_u32(rows, "rmsnorm rows")?;
            let cols_u32 = to_u32(cols, "rmsnorm cols")?;

            let func = self.function(self.modules.rmsnorm, "rmsnorm_kernel")?;
            unsafe {
                func.launch(
                    row_launch(rows_u32),
                    (
                        &input.data,
                        &weight.data,
                        &mut output.data,
                        rows_u32,
                        cols_u32,
                        eps,
                    ),
                )
            }
            .map_err(|err| cuda_error("failed to launch rmsnorm kernel", err))?;
            Ok(())
        }

        pub fn rmsnorm_device_prefix_into(
            &self,
            input: &CudaF32Buffer,
            weight: &CudaF32Buffer,
            rows: usize,
            cols: usize,
            eps: f32,
            output: &mut CudaF32Buffer,
        ) -> Result<()> {
            let expected = checked_mul(rows, cols, "rmsnorm prefix elements")?;
            if input.len() < expected || output.len() < expected {
                return Err(XrtError::Shape(format!(
                    "rmsnorm prefix requires {expected} input/output elements, found input={} output={}",
                    input.len(),
                    output.len()
                )));
            }
            expect_len(weight.len(), cols, "rmsnorm prefix resident weight")?;
            if expected == 0 {
                return Ok(());
            }
            let input_view = input.data.slice(..expected);
            let mut output_view = output.data.slice_mut(..expected);
            let rows_u32 = to_u32(rows, "rmsnorm prefix rows")?;
            let cols_u32 = to_u32(cols, "rmsnorm prefix cols")?;
            let func = self.function(self.modules.rmsnorm, "rmsnorm_kernel")?;
            unsafe {
                func.launch(
                    row_launch(rows_u32),
                    (
                        &input_view,
                        &weight.data,
                        &mut output_view,
                        rows_u32,
                        cols_u32,
                        eps,
                    ),
                )
            }
            .map_err(|err| cuda_error("failed to launch rmsnorm prefix kernel", err))
        }

