        pub fn f16_f32_residual_add_verify_device_into(
            &self,
            projected_f16: &CudaBytes,
            residual: &CudaF32Buffer,
            elements: usize,
            output: &mut CudaF32Buffer,
        ) -> Result<()> {
            if projected_f16.len() < elements.saturating_mul(2)
                || residual.len() < elements
                || output.len() < elements
            {
                return Err(XrtError::Shape(format!(
                    "fused Marlin residual epilogue has incompatible buffers for {elements} elements"
                )));
            }
            if elements == 0 {
                return Ok(());
            }
            let elements = to_u32(elements, "fused Marlin residual elements")?;
            let func = self.function(
                self.modules.q4_k_recurrent,
                "xrt_f16_f32_residual_add_verify",
            )?;
            unsafe {
                func.launch(
                    one_dim_launch(elements),
                    (
                        &projected_f16.data,
                        &residual.data,
                        &mut output.data,
                        elements,
                    ),
                )
            }
            .map_err(|err| cuda_error("failed to launch fused Marlin residual epilogue", err))
        }

        pub fn f16_f32_residual_add_assign_verify_device(
            &self,
            projected_f16: &CudaBytes,
            residual: &mut CudaF32Buffer,
            elements: usize,
        ) -> Result<()> {
            if projected_f16.len() < elements.saturating_mul(2) || residual.len() < elements {
                return Err(XrtError::Shape(format!(
                    "fused Marlin residual-assign epilogue has incompatible buffers for {elements} elements"
                )));
            }
            if elements == 0 {
                return Ok(());
            }
            let elements = to_u32(elements, "fused Marlin residual-assign elements")?;
            let func = self.function(
                self.modules.q4_k_recurrent,
                "xrt_f16_f32_residual_add_verify",
            )?;
            let residual_ptr: *const CudaSlice<f32> = &residual.data;
            let mut params = vec![
                (&projected_f16.data).as_kernel_param(),
                // The kernel reads before writing each independent element;
                // passing the same allocation for residual and output is safe.
                unsafe { (&*residual_ptr).as_kernel_param() },
                (&mut residual.data).as_kernel_param(),
                elements.as_kernel_param(),
            ];
            unsafe { func.launch(one_dim_launch(elements), &mut params) }.map_err(|err| {
                cuda_error(
                    "failed to launch fused Marlin residual-assign epilogue",
                    err,
                )
            })
        }

        pub fn f16_swiglu_f32_verify_device_into(
            &self,
            gate_f16: &CudaBytes,
            up_f16: &CudaBytes,
            elements: usize,
            output: &mut CudaF32Buffer,
        ) -> Result<()> {
            let required_bytes = elements.saturating_mul(2);
            if gate_f16.len() < required_bytes
                || up_f16.len() < required_bytes
                || output.len() < elements
            {
                return Err(XrtError::Shape(format!(
                    "fused Marlin SwiGLU epilogue has incompatible buffers for {elements} elements"
                )));
            }
            if elements == 0 {
                return Ok(());
            }
            let elements = to_u32(elements, "fused Marlin SwiGLU elements")?;
            let func = self.function(self.modules.q4_k_recurrent, "xrt_f16_swiglu_f32_verify")?;
            unsafe {
                func.launch(
                    one_dim_launch(elements),
                    (&gate_f16.data, &up_f16.data, &mut output.data, elements),
                )
            }
            .map_err(|err| cuda_error("failed to launch fused Marlin SwiGLU epilogue", err))
        }

        pub fn matmul_q4_k_f16_tensor_core_verify_resident_device_into(
            &self,
            matrix: &CudaQ4KMatrix,
            input: &CudaBytes,
            batch_rows: usize,
            output: &mut CudaF32Buffer,
        ) -> Result<()> {
            if !self.kquant_tensor_core_verify_enabled {
                return Err(XrtError::Unsupported(
                    "Q4_K F16-input verification requires XRT_CUDA_KQUANT_TENSOR_CORE_VERIFY"
                        .to_string(),
                ));
            }
            if !(2..=16).contains(&batch_rows) {
                return Err(XrtError::Shape(format!(
                    "Q4_K verify matmul requires 2..=16 activation rows, found {batch_rows}"
                )));
            }
            let required_input_bytes = checked_mul(
                checked_mul(batch_rows, matrix.cols, "Q4_K verify input elements")?,
                2,
                "Q4_K F16 verify input bytes",
            )?;
            if input.len() < required_input_bytes {
                return Err(XrtError::Shape(format!(
                    "Q4_K F16 verify input has {} bytes but requires at least {required_input_bytes}",
                    input.len()
                )));
            }
            expect_len(
                output.len(),
                checked_mul(batch_rows, matrix.rows, "Q4_K verify output elements")?,
                "Q4_K verify matmul output",
            )?;
            if matrix.rows == 0 {
                return Ok(());
            }
            let CudaKQuantMatrixStorage::Q4K {
                d,
                dmin,
                scales,
                quants,
            } = &matrix.storage
            else {
                return Err(XrtError::InvalidTensor(
                    "Q4_K verify matmul requires packed Q4_K storage".to_string(),
                ));
            };
            let rows_u32 = to_u32(matrix.rows, "Q4_K verify matmul rows")?;
            let cols_u32 = to_u32(matrix.cols, "Q4_K verify matmul cols")?;
            let kernel = if self.kquant_k2_verify_enabled {
                "xrt_q4_k_tensor_core_verify_k2"
            } else {
                "xrt_q4_k_tensor_core_verify"
            };
            let func = self.function(self.modules.q4_k_recurrent, kernel)?;
            unsafe {
                func.launch(
                    kquant_tensor_core_verify_launch(rows_u32),
                    (
                        &d.data,
                        &dmin.data,
                        &scales.data,
                        &quants.data,
                        &input.data,
                        &mut output.data,
                        rows_u32,
                        cols_u32,
                        to_u32(batch_rows, "Q4_K tensor-core verify activation rows")?,
                        1u32,
                    ),
                )
            }
            .map_err(|err| cuda_error("failed to launch Q4_K F16-input verifier", err))?;
            Ok(())
        }

        pub fn matmul_q4_k_swiglu_verify_resident_device_into(
            &self,
            gate: &CudaQ4KMatrix,
            up: &CudaQ4KMatrix,
            input: &CudaF32Buffer,
            batch_rows: usize,
            output: &mut CudaF32Buffer,
        ) -> Result<()> {
            if !self.kquant_tensor_core_verify_enabled {
                return Err(XrtError::Unsupported(
                    "fused Q4_K SwiGLU verification requires XRT_CUDA_KQUANT_TENSOR_CORE_VERIFY"
                        .to_string(),
                ));
            }
            if !(2..=16).contains(&batch_rows) {
                return Err(XrtError::Shape(format!(
                    "fused Q4_K SwiGLU verification requires 2..=16 activation rows, found {batch_rows}"
                )));
            }
            if gate.rows != up.rows || gate.cols != up.cols {
                return Err(XrtError::Shape(format!(
                    "fused Q4_K SwiGLU matrices must match, found {}x{} and {}x{}",
                    gate.rows, gate.cols, up.rows, up.cols
                )));
            }
            expect_len(
                input.len(),
                checked_mul(batch_rows, gate.cols, "fused Q4_K SwiGLU input elements")?,
                "fused Q4_K SwiGLU input",
            )?;
            expect_len(
                output.len(),
                checked_mul(batch_rows, gate.rows, "fused Q4_K SwiGLU output elements")?,
                "fused Q4_K SwiGLU output",
            )?;
            if gate.rows == 0 {
                return Ok(());
            }
            let CudaKQuantMatrixStorage::Q4K {
                d: gate_d,
                dmin: gate_dmin,
                scales: gate_scales,
                quants: gate_quants,
            } = &gate.storage
            else {
                return Err(XrtError::InvalidTensor(
                    "fused Q4_K SwiGLU gate requires packed Q4_K storage".to_string(),
                ));
            };
            let CudaKQuantMatrixStorage::Q4K {
                d: up_d,
                dmin: up_dmin,
                scales: up_scales,
                quants: up_quants,
            } = &up.storage
            else {
                return Err(XrtError::InvalidTensor(
                    "fused Q4_K SwiGLU up projection requires packed Q4_K storage".to_string(),
                ));
            };
            let rows_u32 = to_u32(gate.rows, "fused Q4_K SwiGLU rows")?;
            let func = self.function(
                self.modules.q4_k_recurrent,
                "xrt_q4_k_tensor_core_swiglu_verify",
            )?;
            let cols_u32 = to_u32(gate.cols, "fused Q4_K SwiGLU columns")?;
            let activation_rows_u32 = to_u32(batch_rows, "fused Q4_K SwiGLU activation rows")?;
            let mut params = vec![
                (&gate_d.data).as_kernel_param(),
                (&gate_dmin.data).as_kernel_param(),
                (&gate_scales.data).as_kernel_param(),
                (&gate_quants.data).as_kernel_param(),
                (&up_d.data).as_kernel_param(),
                (&up_dmin.data).as_kernel_param(),
                (&up_scales.data).as_kernel_param(),
                (&up_quants.data).as_kernel_param(),
                (&input.data).as_kernel_param(),
                (&mut output.data).as_kernel_param(),
                rows_u32.as_kernel_param(),
                cols_u32.as_kernel_param(),
                activation_rows_u32.as_kernel_param(),
            ];
            unsafe { func.launch(q4_k_swiglu_verify_launch(rows_u32), &mut params) }
                .map_err(|err| cuda_error("failed to launch fused Q4_K SwiGLU verifier", err))?;
            Ok(())
        }

        pub fn matvec_q5_k(
            &self,
            matrix: &[u8],
            rows: usize,
            cols: usize,
            input: &[f32],
        ) -> Result<Vec<f32>> {
            let resident = self.upload_q5_k_matrix(matrix, rows, cols)?;
            self.matvec_q5_k_resident(&resident, input)
        }

        /// Exact row-batched Q5_K projection for an MTP verification window.
        /// Decoding each packed row once preserves the recurrent matvec's FMA
        /// and reduction order while reusing weights across 2..=16 activations.
        pub fn matmul_q5_k_verify_resident_device(
            &self,
            matrix: &CudaQ5KMatrix,
            input: &CudaF32Buffer,
            batch_rows: usize,
        ) -> Result<CudaF32Buffer> {
            let mut output = self.zeros_f32(checked_mul(
                batch_rows,
                matrix.rows,
                "Q5_K verify output elements",
            )?)?;
            self.matmul_q5_k_verify_resident_device_into(matrix, input, batch_rows, &mut output)?;
            Ok(output)
        }

        pub fn matmul_q5_k_verify_resident_device_into(
            &self,
            matrix: &CudaQ5KMatrix,
            input: &CudaF32Buffer,
            batch_rows: usize,
            output: &mut CudaF32Buffer,
        ) -> Result<()> {
            self.matmul_q5_k_verify_resident_device_into_on_stream(
                matrix, input, batch_rows, output, None,
            )
        }

        pub fn matmul_q5_k_verify_resident_device_into_on_stream(
            &self,
            matrix: &CudaQ5KMatrix,
            input: &CudaF32Buffer,
            batch_rows: usize,
            output: &mut CudaF32Buffer,
            stream: Option<&CudaExecutionStream>,
        ) -> Result<()> {
            if !(2..=16).contains(&batch_rows) {
                return Err(XrtError::Shape(format!(
                    "Q5_K verify matmul requires 2..=16 activation rows, found {batch_rows}"
                )));
            }
            expect_len(
                input.len(),
                checked_mul(batch_rows, matrix.cols, "Q5_K verify input elements")?,
                "Q5_K verify matmul input",
            )?;
            expect_len(
                output.len(),
                checked_mul(batch_rows, matrix.rows, "Q5_K verify output elements")?,
                "Q5_K verify matmul output",
            )?;
            if matrix.rows == 0 {
                return Ok(());
            }
            if let CudaKQuantMatrixStorage::Q5KMarlin { matrix: marlin } = &matrix.storage {
                return self.matmul_q5_k_marlin_f32_into_on_stream(
                    marlin, input, batch_rows, output, stream,
                );
            }
            let CudaKQuantMatrixStorage::Q5K {
                d,
                dmin,
                scales,
                high_bits,
                quants,
                verify_input_f16,
                verify_weights_f16,
            } = &matrix.storage
            else {
                return Err(XrtError::InvalidTensor(
                    "Q5_K verify matmul requires packed Q5_K storage".to_string(),
                ));
            };
            let rows_u32 = to_u32(matrix.rows, "Q5_K verify matmul rows")?;
            let cols_u32 = to_u32(matrix.cols, "Q5_K verify matmul cols")?;
            if let Some(weights) = verify_weights_f16 {
                let scratch = verify_input_f16.as_ref().ok_or_else(|| {
                    XrtError::Runtime(
                        "Q5_K F16-weight verifier is missing its F16 input scratch".to_string(),
                    )
                })?;
                let mut scratch = scratch
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner());
                self.convert_f32_to_f16_verify_into_on_stream(input, &mut scratch, stream)?;
                let func = self.function(
                    self.modules.q4_k_recurrent,
                    "xrt_q5_k_f16_weight_tensor_core_verify",
                )?;
                let params = (
                    &weights.data,
                    &scratch.data,
                    &mut output.data,
                    rows_u32,
                    cols_u32,
                    to_u32(batch_rows, "Q5_K F16-weight verify activation rows")?,
                );
                let launch = LaunchConfig {
                    grid_dim: (rows_u32.div_ceil(128), 1, 1),
                    block_dim: (32, 8, 1),
                    shared_mem_bytes: 0,
                };
                unsafe {
                    match stream {
                        Some(stream) => func.launch_on_stream(&stream.stream, launch, params),
                        None => func.launch(launch, params),
                    }
                }
                .map_err(|err| {
                    cuda_error("failed to launch Q5_K F16-weight tensor-core verifier", err)
                })?;
                return Ok(());
            }
            if self.kquant_mmq_enabled {
                if stream.is_some() {
                    return Err(XrtError::Unsupported(
                        "Q5_K MMQ does not support auxiliary execution streams".to_string(),
                    ));
                }
                self.matmul_q5_k_q8_mmq_into(
                    d,
                    dmin,
                    scales,
                    high_bits,
                    quants,
                    input,
                    output,
                    matrix.rows,
                    matrix.cols,
                    batch_rows,
                )?;
                return Ok(());
            }
            if self.kquant_tensor_core_verify_enabled {
                if let Some(scratch) = verify_input_f16 {
                    let mut scratch = scratch
                        .lock()
                        .unwrap_or_else(|poisoned| poisoned.into_inner());
                    self.convert_f32_to_f16_verify_into_on_stream(input, &mut scratch, stream)?;
                    let func = self.function(
                        self.modules.q4_k_recurrent,
                        "xrt_q5_k_tensor_core_verify_f16_input",
                    )?;
                    let params = (
                        &d.data,
                        &dmin.data,
                        &scales.data,
                        &high_bits.data,
                        &quants.data,
                        &scratch.data,
                        &mut output.data,
                        rows_u32,
                        cols_u32,
                        to_u32(batch_rows, "Q5_K F16 tensor-core verify activation rows")?,
                    );
                    unsafe {
                        match stream {
                            Some(stream) => func.launch_on_stream(
                                &stream.stream,
                                kquant_tensor_core_verify_launch(rows_u32),
                                params,
                            ),
                            None => func.launch(kquant_tensor_core_verify_launch(rows_u32), params),
                        }
                    }
                    .map_err(|err| {
                        cuda_error("failed to launch Q5_K F16-input tensor-core verifier", err)
                    })?;
                    return Ok(());
                }
                let (kernel, launch) = if self.q5_k_n32_verify_enabled {
                    (
                        "xrt_q5_k_tensor_core_verify_n32",
                        kquant_tensor_core_n32_verify_launch(rows_u32),
                    )
                } else if self.kquant_tensor_core_pipelined_verify_enabled {
                    (
                        "xrt_q5_k_tensor_core_verify_pipelined",
                        kquant_tensor_core_pipelined_verify_launch(rows_u32),
                    )
                } else {
                    (
                        "xrt_q5_k_tensor_core_verify",
                        kquant_tensor_core_verify_launch(rows_u32),
                    )
                };
                let func = self.function(self.modules.q4_k_recurrent, kernel)?;
                let params = (
                    &d.data,
                    &dmin.data,
                    &scales.data,
                    &high_bits.data,
                    &quants.data,
                    &input.data,
                    &mut output.data,
                    rows_u32,
                    cols_u32,
                    to_u32(batch_rows, "Q5_K tensor-core verify activation rows")?,
                );
                unsafe {
                    match stream {
                        Some(stream) => func.launch_on_stream(&stream.stream, launch, params),
                        None => func.launch(launch, params),
                    }
                }
                .map_err(|err| cuda_error("failed to launch Q5_K tensor-core verifier", err))?;
                return Ok(());
            }
            let verify_rows = match batch_rows {
                2..=4 => 4,
                5..=8 => 8,
                9..=16 => 16,
                _ => unreachable!("Q5_K verify row count was validated above"),
            };
            let kernel = match verify_rows {
                4 => "xrt_q5_k_verify_matmul_4",
                8 => "xrt_q5_k_verify_matmul_8",
                16 => "xrt_q5_k_verify_matmul_16",
                _ => unreachable!("Q5_K verify bucket is fixed"),
            };
            let func = self.function(self.modules.q4_k_recurrent, kernel)?;
            let params = (
                &d.data,
                &dmin.data,
                &scales.data,
                &high_bits.data,
                &quants.data,
                &input.data,
                &mut output.data,
                rows_u32,
                cols_u32,
                to_u32(batch_rows, "Q5_K verify activation rows")?,
            );
            unsafe {
                match stream {
                    Some(stream) => func.launch_on_stream(
                        &stream.stream,
                        q4_k_verify_launch(rows_u32, verify_rows),
                        params,
                    ),
                    None => func.launch(q4_k_verify_launch(rows_u32, verify_rows), params),
                }
            }
            .map_err(|err| cuda_error("failed to launch Q5_K verify matmul kernel", err))?;
            Ok(())
        }

        pub fn matvec_q5_k_resident(
            &self,
            matrix: &CudaQ5KMatrix,
            input: &[f32],
        ) -> Result<Vec<f32>> {
            let input = self.upload_f32(input)?;
            self.matvec_q5_k_resident_device(matrix, &input)
                .and_then(|output| self.download_f32(&output))
        }

        pub fn matvec_q5_k_resident_device(
            &self,
            matrix: &CudaQ5KMatrix,
            input: &CudaF32Buffer,
        ) -> Result<CudaF32Buffer> {
            let mut output = self.zeros_f32(matrix.rows)?;
            self.matvec_q5_k_resident_device_into(matrix, input, &mut output)?;
            Ok(output)
        }

        pub fn matvec_q5_k_resident_device_into(
            &self,
            matrix: &CudaQ5KMatrix,
            input: &CudaF32Buffer,
            output: &mut CudaF32Buffer,
        ) -> Result<()> {
            expect_len(input.len(), matrix.cols, "Q5_K matvec input")?;
            expect_len(output.len(), matrix.rows, "Q5_K matvec output")?;
            if matrix.rows == 0 {
                return Ok(());
            }
            match &matrix.storage {
                CudaKQuantMatrixStorage::Q5K {
                    d,
                    dmin,
                    scales,
                    high_bits,
                    quants,
                    ..
                } => {
                    let rows_u32 = to_u32(matrix.rows, "Q5_K matvec rows")?;
                    let cols_u32 = to_u32(matrix.cols, "Q5_K matvec cols")?;
                    let func =
                        self.function(self.modules.q4_k_recurrent, "xrt_q5_k_cpu_order_matvec")?;
                    unsafe {
                        func.launch(
                            q4_k_recurrent_launch(rows_u32),
                            (
                                &d.data,
                                &dmin.data,
                                &scales.data,
                                &high_bits.data,
                                &quants.data,
                                &input.data,
                                &mut output.data,
                                rows_u32,
                                cols_u32,
                            ),
                        )
                    }
                    .map_err(|err| {
                        cuda_error("failed to launch CPU-order Q5_K matvec kernel", err)
                    })?;
                    Ok(())
                }
                CudaKQuantMatrixStorage::Q5KMarlin { matrix: marlin } => {
                    self.matmul_q5_k_marlin_f32_into_on_stream(marlin, input, 1, output, None)
                }
                CudaKQuantMatrixStorage::ExpandedF32 {
                    values_transposed, ..
                } => self.matmul_resident_rhs_device_into(
                    input,
                    1,
                    matrix.cols,
                    values_transposed,
                    matrix.rows,
                    output,
                ),
                CudaKQuantMatrixStorage::Q4K { .. } => Err(XrtError::InvalidTensor(
                    "Q5_K matvec received packed Q4_K storage".to_string(),
                )),
                CudaKQuantMatrixStorage::Q4KMarlin { .. } => Err(XrtError::InvalidTensor(
                    "Q5_K matvec received Marlin Q4_K storage".to_string(),
                )),
                CudaKQuantMatrixStorage::Q6K { .. } | CudaKQuantMatrixStorage::Q6KMarlin { .. } => {
                    Err(XrtError::InvalidTensor(
                        "Q5_K matvec received Q6_K storage".to_string(),
                    ))
                }
            }
        }

        fn matmul_q5_k_q8_mmq_into(
            &self,
            d: &CudaF32Buffer,
            dmin: &CudaF32Buffer,
            scales: &CudaBytes,
            high_bits: &CudaBytes,
            quants: &CudaBytes,
            input: &CudaF32Buffer,
            output: &mut CudaF32Buffer,
            rows: usize,
            cols: usize,
            batch_rows: usize,
        ) -> Result<()> {
            let (quant_count, quant_blocks, workspace_bytes) =
                kquant_mmq_workspace_geometry(batch_rows, cols)?;
            let rows_u32 = to_u32(rows, "Q5_K MMQ weight rows")?;
            let cols_u32 = to_u32(cols, "Q5_K MMQ weight cols")?;
            let batch_rows_u32 = to_u32(batch_rows, "Q5_K MMQ activation rows")?;
            let quant_count_u32 = to_u32(quant_count, "Q5_K MMQ activation elements")?;
            let quant_blocks_u32 = to_u32(quant_blocks, "Q5_K MMQ activation blocks")?;
            self.with_kquant_workspace(workspace_bytes, |workspace| {
                self.quantize_q8_mmq_into(input, workspace, quant_count, quant_blocks)?;
                let kernel = "xrt_q5_k_q8_mmq";
                let launch = kquant_mmq_launch(rows_u32, batch_rows_u32);
                let func = self.function(self.modules.kquant_mmq, kernel)?;
                unsafe {
                    func.launch(
                        launch,
                        (
                            &d.data,
                            &dmin.data,
                            &scales.data,
                            &high_bits.data,
                            &quants.data,
                            &workspace.data,
                            &mut output.data,
                            rows_u32,
                            cols_u32,
                            batch_rows_u32,
                            quant_count_u32,
                            quant_blocks_u32,
                        ),
                    )
                }
                .map_err(|err| cuda_error("failed to launch Q5_K Q8 MMQ", err))?;
                Ok(())
            })
        }

        /// Row-batched Q5_K matrix multiplication with packed resident weights.
        /// Image-sized batches use Q8-activation DP4A with an F32 CUDA fallback.
        pub fn matmul_q5_k_resident_device(
            &self,
            matrix: &CudaQ5KMatrix,
            input: &CudaF32Buffer,
            batch_rows: usize,
        ) -> Result<CudaF32Buffer> {
            let input_len = checked_mul(batch_rows, matrix.cols, "Q5_K matmul input elements")?;
            let output_len = checked_mul(batch_rows, matrix.rows, "Q5_K matmul output elements")?;
            expect_len(input.len(), input_len, "Q5_K matmul input")?;
            let mut output = self.zeros_f32(output_len)?;
            if batch_rows == 0 || matrix.rows == 0 {
                return Ok(output);
            }

            match &matrix.storage {
                CudaKQuantMatrixStorage::Q5K {
                    d,
                    dmin,
                    scales,
                    high_bits,
                    quants,
                    ..
                } => {
                    let rows_u32 = to_u32(matrix.rows, "Q5_K matmul weight rows")?;
                    let cols_u32 = to_u32(matrix.cols, "Q5_K matmul weight cols")?;
                    if self.kquant_mmq_enabled
                        && batch_rows >= 16
                        && batch_rows <= CUDA_GRID_Y_MAX * 8
                    {
                        match self.matmul_q5_k_q8_mmq_into(
                            d,
                            dmin,
                            scales,
                            high_bits,
                            quants,
                            input,
                            &mut output,
                            matrix.rows,
                            matrix.cols,
                            batch_rows,
                        ) {
                            Ok(()) => return Ok(output),
                            Err(error) => warn!(
                                error = %error,
                                "Q5_K Q8 MMQ unavailable; falling back to the F32 CUDA tile"
                            ),
                        }
                    }
                    if batch_rows >= 16 && batch_rows <= CUDA_GRID_Y_MAX * 16 {
                        let batch_rows_u32 =
                            to_u32(batch_rows, "Q5_K tiled matmul activation rows")?;
                        let func =
                            self.function(self.modules.q4_k_recurrent, "xrt_q5_k_tiled_matmul")?;
                        unsafe {
                            func.launch(
                                kquant_tiled_launch(rows_u32, batch_rows_u32),
                                (
                                    &d.data,
                                    &dmin.data,
                                    &scales.data,
                                    &high_bits.data,
                                    &quants.data,
                                    &input.data,
                                    &mut output.data,
                                    rows_u32,
                                    cols_u32,
                                    batch_rows_u32,
                                ),
                            )
                        }
                        .map_err(|err| cuda_error("failed to launch tiled Q5_K matmul", err))?;
                        return Ok(output);
                    }
                    let func =
                        self.function(self.modules.q4_k_recurrent, "xrt_q5_k_cpu_order_matvec")?;
                    for batch_start in (0..batch_rows).step_by(CUDA_GRID_Y_MAX) {
                        let batch_end = batch_start.saturating_add(CUDA_GRID_Y_MAX).min(batch_rows);
                        let input_start = batch_start * matrix.cols;
                        let input_end = batch_end * matrix.cols;
                        let output_start = batch_start * matrix.rows;
                        let output_end = batch_end * matrix.rows;
                        let input_view = input.data.slice(input_start..input_end);
                        let mut output_view = output.data.slice_mut(output_start..output_end);
                        unsafe {
                            func.clone().launch(
                                q4_k_recurrent_batch_launch(
                                    rows_u32,
                                    to_u32(batch_end - batch_start, "Q5_K matmul batch rows")?,
                                ),
                                (
                                    &d.data,
                                    &dmin.data,
                                    &scales.data,
                                    &high_bits.data,
                                    &quants.data,
                                    &input_view,
                                    &mut output_view,
                                    rows_u32,
                                    cols_u32,
                                ),
                            )
                        }
                        .map_err(|err| {
                            cuda_error("failed to launch batched Q5_K matmul chunk", err)
                        })?;
                    }
                    Ok(output)
                }
                CudaKQuantMatrixStorage::Q5KMarlin { matrix: marlin } => {
                    if batch_rows <= 16 {
                        self.matmul_q5_k_marlin_f32_into_on_stream(
                            marlin,
                            input,
                            batch_rows,
                            &mut output,
                            None,
                        )?;
                        return Ok(output);
                    }
                    for batch_start in (0..batch_rows).step_by(16) {
                        let batch_end = batch_start.saturating_add(16).min(batch_rows);
                        let chunk_rows = batch_end - batch_start;
                        let mut chunk_input = self.zeros_f32(checked_mul(
                            chunk_rows,
                            matrix.cols,
                            "Marlin Q5_K prompt input elements",
                        )?)?;
                        self.copy_f32_device_range(
                            input,
                            batch_start * matrix.cols,
                            &mut chunk_input,
                        )?;
                        let mut chunk_output = self.zeros_f32(checked_mul(
                            chunk_rows,
                            matrix.rows,
                            "Marlin Q5_K prompt output elements",
                        )?)?;
                        self.matmul_q5_k_marlin_f32_into_on_stream(
                            marlin,
                            &chunk_input,
                            chunk_rows,
                            &mut chunk_output,
                            None,
                        )?;
                        self.copy_f32_device_into_range(
                            &chunk_output,
                            &mut output,
                            batch_start * matrix.rows,
                        )?;
                    }
                    Ok(output)
                }
                CudaKQuantMatrixStorage::ExpandedF32 {
                    values_transposed, ..
                } => self.matmul_resident_rhs_device(
                    input,
                    batch_rows,
                    matrix.cols,
                    values_transposed,
                    matrix.rows,
                ),
                CudaKQuantMatrixStorage::Q4K { .. } => Err(XrtError::InvalidTensor(
                    "Q5_K matmul received packed Q4_K storage".to_string(),
                )),
                CudaKQuantMatrixStorage::Q4KMarlin { .. } => Err(XrtError::InvalidTensor(
                    "Q5_K matmul received Marlin Q4_K storage".to_string(),
                )),
                CudaKQuantMatrixStorage::Q6K { .. } | CudaKQuantMatrixStorage::Q6KMarlin { .. } => {
                    Err(XrtError::InvalidTensor(
                        "Q5_K matmul received Q6_K storage".to_string(),
                    ))
                }
            }
        }

        pub fn matvec_q6_k(
            &self,
            matrix: &[u8],
            rows: usize,
            cols: usize,
            input: &[f32],
        ) -> Result<Vec<f32>> {
            let resident = self.upload_q6_k_matrix(matrix, rows, cols)?;
            self.matvec_q6_k_resident(&resident, input)
        }

        pub fn matvec_q6_k_resident(
            &self,
            matrix: &CudaQ6KMatrix,
            input: &[f32],
        ) -> Result<Vec<f32>> {
            let input = self.upload_f32(input)?;
            self.matvec_q6_k_resident_device(matrix, &input)
                .and_then(|output| self.download_f32(&output))
        }

        pub fn matvec_q6_k_resident_device(
            &self,
            matrix: &CudaQ6KMatrix,
            input: &CudaF32Buffer,
        ) -> Result<CudaF32Buffer> {
            let mut output = self.zeros_f32(matrix.rows)?;
            self.matvec_q6_k_resident_device_into(matrix, input, &mut output)?;
            Ok(output)
        }

        pub fn matvec_q6_k_resident_device_into(
            &self,
            matrix: &CudaQ6KMatrix,
            input: &CudaF32Buffer,
            output: &mut CudaF32Buffer,
        ) -> Result<()> {
            expect_len(input.len(), matrix.cols, "Q6_K matvec input")?;
            expect_len(output.len(), matrix.rows, "Q6_K matvec output")?;
            if matrix.rows == 0 {
                return Ok(());
            }
            match &matrix.storage {
                CudaKQuantMatrixStorage::Q6K { d, blocks, .. } => {
                    let rows_u32 = to_u32(matrix.rows, "Q6_K matvec rows")?;
                    let cols_u32 = to_u32(matrix.cols, "Q6_K matvec cols")?;
                    let func = self.function(self.modules.q6_k_matvec, "q6_k_matvec_kernel")?;
                    unsafe {
                        func.launch(
                            row_launch(rows_u32),
                            (
                                &d.data,
                                &blocks.data,
                                &input.data,
                                &mut output.data,
                                rows_u32,
                                cols_u32,
                            ),
                        )
                    }
                    .map_err(|err| cuda_error("failed to launch Q6_K matvec kernel", err))?;
                    Ok(())
                }
                CudaKQuantMatrixStorage::Q6KMarlin { matrix: marlin } => {
                    self.matmul_q6_k_marlin_f32_into_on_stream(marlin, input, 1, output, None)
                }
                CudaKQuantMatrixStorage::Q4K { .. } => Err(XrtError::InvalidTensor(
                    "Q6_K matvec received packed Q4_K storage".to_string(),
                )),
                CudaKQuantMatrixStorage::Q4KMarlin { .. } => Err(XrtError::InvalidTensor(
                    "Q6_K matvec received Marlin Q4_K storage".to_string(),
                )),
                CudaKQuantMatrixStorage::Q5K { .. } | CudaKQuantMatrixStorage::Q5KMarlin { .. } => {
                    Err(XrtError::InvalidTensor(
                        "Q6_K matvec received packed Q5_K storage".to_string(),
                    ))
                }
                CudaKQuantMatrixStorage::ExpandedF32 {
                    values_transposed, ..
                } => self.matmul_resident_rhs_device_into(
                    input,
                    1,
                    matrix.cols,
                    values_transposed,
                    matrix.rows,
                    output,
                ),
            }
        }

        /// Projects only the leading output rows of a packed Q6_K matrix.
        /// This is used by speculative draft heads whose proposals may use a
        /// vocabulary prefix while the target verifier remains full-vocabulary.
        pub fn matvec_q6_k_resident_prefix_device_into(
            &self,
            matrix: &CudaQ6KMatrix,
            input: &CudaF32Buffer,
            prefix_rows: usize,
            output: &mut CudaF32Buffer,
        ) -> Result<()> {
            expect_len(input.len(), matrix.cols, "Q6_K prefix matvec input")?;
            if output.len() < prefix_rows {
                return Err(XrtError::Shape(format!(
                    "Q6_K prefix matvec output length {} is smaller than {prefix_rows}",
                    output.len()
                )));
            }
            if prefix_rows > matrix.rows {
                return Err(XrtError::Shape(format!(
                    "Q6_K prefix rows {prefix_rows} exceed matrix rows {}",
                    matrix.rows
                )));
            }
            if prefix_rows == 0 {
                return Ok(());
            }
            let CudaKQuantMatrixStorage::Q6K { d, blocks, .. } = &matrix.storage else {
                return Err(XrtError::InvalidTensor(
                    "Q6_K prefix matvec requires packed Q6_K storage".to_string(),
                ));
            };
            let rows_u32 = to_u32(prefix_rows, "Q6_K prefix matvec rows")?;
            let cols_u32 = to_u32(matrix.cols, "Q6_K prefix matvec cols")?;
            let func = self.function(self.modules.q6_k_matvec, "q6_k_matvec_kernel")?;
            unsafe {
                func.launch(
                    row_launch(rows_u32),
                    (
                        &d.data,
                        &blocks.data,
                        &input.data,
                        &mut output.data,
                        rows_u32,
                        cols_u32,
                    ),
                )
            }
            .map_err(|err| cuda_error("failed to launch Q6_K prefix matvec kernel", err))?;
            Ok(())
        }

        /// Projects one speculative row with the existing Q6_K WMMA verifier.
        /// Unused activation rows in its 16x16 tile are zero padded. Because
        /// this changes only draft proposals, the target verifier remains the
        /// authority for every published token.
        pub fn matvec_q6_k_resident_prefix_tensor_core_device_into(
            &self,
            matrix: &CudaQ6KMatrix,
            input: &CudaF32Buffer,
            prefix_rows: usize,
            output: &mut CudaF32Buffer,
        ) -> Result<()> {
            expect_len(input.len(), matrix.cols, "Q6_K prefix tensor-core input")?;
            if output.len() < prefix_rows {
                return Err(XrtError::Shape(format!(
                    "Q6_K prefix tensor-core output length {} is smaller than {prefix_rows}",
                    output.len()
                )));
            }
            if prefix_rows > matrix.rows {
                return Err(XrtError::Shape(format!(
                    "Q6_K prefix tensor-core rows {prefix_rows} exceed matrix rows {}",
                    matrix.rows
                )));
            }
            if prefix_rows == 0 {
                return Ok(());
            }
            let CudaKQuantMatrixStorage::Q6K { d, blocks, .. } = &matrix.storage else {
                return Err(XrtError::InvalidTensor(
                    "Q6_K prefix tensor-core projection requires packed Q6_K storage".to_string(),
                ));
            };
            let rows_u32 = to_u32(prefix_rows, "Q6_K prefix tensor-core rows")?;
            let func = self.function(self.modules.q4_k_recurrent, "xrt_q6_k_tensor_core_verify")?;
            unsafe {
                func.launch(
                    kquant_tensor_core_verify_launch(rows_u32),
                    (
                        &d.data,
                        &blocks.data,
                        &input.data,
                        &mut output.data,
                        rows_u32,
                        to_u32(matrix.cols, "Q6_K prefix tensor-core columns")?,
                        1_u32,
                    ),
                )
            }
            .map_err(|err| cuda_error("failed to launch Q6_K prefix tensor-core head", err))?;
            Ok(())
        }

        fn matmul_q6_k_q8_mmq_into(
            &self,
            d: &CudaF32Buffer,
            blocks: &CudaBytes,
            input: &CudaF32Buffer,
            output: &mut CudaF32Buffer,
            rows: usize,
            cols: usize,
            batch_rows: usize,
        ) -> Result<()> {
            let (quant_count, quant_blocks, workspace_bytes) =
                kquant_mmq_workspace_geometry(batch_rows, cols)?;
            let rows_u32 = to_u32(rows, "Q6_K MMQ weight rows")?;
            let cols_u32 = to_u32(cols, "Q6_K MMQ weight cols")?;
            let batch_rows_u32 = to_u32(batch_rows, "Q6_K MMQ activation rows")?;
            let quant_count_u32 = to_u32(quant_count, "Q6_K MMQ activation elements")?;
            let quant_blocks_u32 = to_u32(quant_blocks, "Q6_K MMQ activation blocks")?;
            self.with_kquant_workspace(workspace_bytes, |workspace| {
                self.quantize_q8_mmq_into(input, workspace, quant_count, quant_blocks)?;
                let func = self.function(self.modules.kquant_mmq, "xrt_q6_k_q8_mmq")?;
                unsafe {
                    func.launch(
                        kquant_mmq_launch(rows_u32, batch_rows_u32),
                        (
                            &d.data,
                            &blocks.data,
                            &workspace.data,
                            &mut output.data,
                            rows_u32,
                            cols_u32,
                            batch_rows_u32,
                            quant_count_u32,
                            quant_blocks_u32,
                        ),
                    )
                }
                .map_err(|err| cuda_error("failed to launch Q6_K Q8 MMQ", err))?;
                Ok(())
            })
        }

        /// Row-batched Q6_K matrix multiplication with packed resident weights.
        /// Image-sized batches use signed Q8 DP4A with an F32 CUDA fallback.
        pub fn matmul_q6_k_resident_device(
            &self,
            matrix: &CudaQ6KMatrix,
            input: &CudaF32Buffer,
            batch_rows: usize,
        ) -> Result<CudaF32Buffer> {
            let input_len = checked_mul(batch_rows, matrix.cols, "Q6_K matmul input elements")?;
            let output_len = checked_mul(batch_rows, matrix.rows, "Q6_K matmul output elements")?;
            expect_len(input.len(), input_len, "Q6_K matmul input")?;
            let mut output = self.zeros_f32(output_len)?;
            self.matmul_q6_k_resident_device_into(matrix, input, batch_rows, &mut output)?;
            Ok(output)
        }

        pub fn matmul_q6_k_resident_device_into(
            &self,
            matrix: &CudaQ6KMatrix,
            input: &CudaF32Buffer,
            batch_rows: usize,
            output: &mut CudaF32Buffer,
        ) -> Result<()> {
            let input_len = checked_mul(batch_rows, matrix.cols, "Q6_K matmul input elements")?;
            let output_len = checked_mul(batch_rows, matrix.rows, "Q6_K matmul output elements")?;
            expect_len(input.len(), input_len, "Q6_K matmul input")?;
            expect_len(output.len(), output_len, "Q6_K matmul output")?;
            if batch_rows == 0 || matrix.rows == 0 {
                return Ok(());
            }

            match &matrix.storage {
                CudaKQuantMatrixStorage::Q6K {
                    d,
                    blocks,
                    verify_input_f16,
                } => {
                    let rows_u32 = to_u32(matrix.rows, "Q6_K matmul weight rows")?;
                    let cols_u32 = to_u32(matrix.cols, "Q6_K matmul weight cols")?;
                    if self.kquant_tensor_core_verify_enabled && (2..=16).contains(&batch_rows) {
                        if let Some(scratch) = verify_input_f16 {
                            let mut scratch = scratch
                                .lock()
                                .unwrap_or_else(|poisoned| poisoned.into_inner());
                            self.convert_f32_to_f16_verify_into(input, &mut scratch)?;
                            let func = self.function(
                                self.modules.q4_k_recurrent,
                                "xrt_q6_k_tensor_core_verify_f16_input",
                            )?;
                            unsafe {
                                func.launch(
                                    kquant_tensor_core_verify_launch(rows_u32),
                                    (
                                        &d.data,
                                        &blocks.data,
                                        &scratch.data,
                                        &mut output.data,
                                        rows_u32,
                                        cols_u32,
                                        to_u32(
                                            batch_rows,
                                            "Q6_K F16 tensor-core verify activation rows",
                                        )?,
                                    ),
                                )
                            }
                            .map_err(|err| {
                                cuda_error(
                                    "failed to launch Q6_K F16-input tensor-core verifier",
                                    err,
                                )
                            })?;
                            return Ok(());
                        }
                        let (kernel, launch) = if self.q6_k_n64_verify_enabled {
                            (
                                "xrt_q6_k_tensor_core_verify_n64",
                                kquant_tensor_core_n64_verify_launch(rows_u32),
                            )
                        } else {
                            (
                                "xrt_q6_k_tensor_core_verify",
                                kquant_tensor_core_verify_launch(rows_u32),
                            )
                        };
                        let func = self.function(self.modules.q4_k_recurrent, kernel)?;
                        unsafe {
                            func.launch(
                                launch,
                                (
                                    &d.data,
                                    &blocks.data,
                                    &input.data,
                                    &mut output.data,
                                    rows_u32,
                                    cols_u32,
                                    to_u32(batch_rows, "Q6_K tensor-core verify activation rows")?,
                                ),
                            )
                        }
                        .map_err(|err| {
                            cuda_error("failed to launch Q6_K tensor-core verifier", err)
                        })?;
                        return Ok(());
                    }
                    if self.kquant_mmq_enabled
                        && batch_rows >= 16
                        && batch_rows <= CUDA_GRID_Y_MAX * 8
                    {
                        match self.matmul_q6_k_q8_mmq_into(
                            d,
                            blocks,
                            input,
                            output,
                            matrix.rows,
                            matrix.cols,
                            batch_rows,
                        ) {
                            Ok(()) => return Ok(()),
                            Err(error) => warn!(
                                error = %error,
                                "Q6_K Q8 MMQ unavailable; falling back to the F32 CUDA tile"
                            ),
                        }
                    }
                    if batch_rows >= 2 && batch_rows <= CUDA_GRID_Y_MAX * 16 {
                        let batch_rows_u32 =
                            to_u32(batch_rows, "Q6_K tiled matmul activation rows")?;
                        let func =
                            self.function(self.modules.q4_k_recurrent, "xrt_q6_k_tiled_matmul")?;
                        unsafe {
                            func.launch(
                                kquant_tiled_launch(rows_u32, batch_rows_u32),
                                (
                                    &d.data,
                                    &blocks.data,
                                    &input.data,
                                    &mut output.data,
                                    rows_u32,
                                    cols_u32,
                                    batch_rows_u32,
                                ),
                            )
                        }
                        .map_err(|err| cuda_error("failed to launch tiled Q6_K matmul", err))?;
                        return Ok(());
                    }
                    let func = self.function(self.modules.q6_k_matvec, "q6_k_matvec_kernel")?;
                    for batch_start in (0..batch_rows).step_by(CUDA_GRID_Y_MAX) {
                        let batch_end = batch_start.saturating_add(CUDA_GRID_Y_MAX).min(batch_rows);
                        let input_start = batch_start * matrix.cols;
                        let input_end = batch_end * matrix.cols;
                        let output_start = batch_start * matrix.rows;
                        let output_end = batch_end * matrix.rows;
                        let input_view = input.data.slice(input_start..input_end);
                        let mut output_view = output.data.slice_mut(output_start..output_end);
                        unsafe {
                            func.clone().launch(
                                row_batch_launch(
                                    rows_u32,
                                    to_u32(batch_end - batch_start, "Q6_K matmul batch rows")?,
                                ),
                                (
                                    &d.data,
                                    &blocks.data,
                                    &input_view,
                                    &mut output_view,
                                    rows_u32,
                                    cols_u32,
                                ),
                            )
                        }
                        .map_err(|err| {
                            cuda_error("failed to launch batched Q6_K matmul chunk", err)
                        })?;
                    }
                    Ok(())
                }
                CudaKQuantMatrixStorage::Q6KMarlin { matrix: marlin } => {
                    if batch_rows <= 16 {
                        return self.matmul_q6_k_marlin_f32_into_on_stream(
                            marlin, input, batch_rows, output, None,
                        );
                    }
                    for batch_start in (0..batch_rows).step_by(16) {
                        let batch_end = batch_start.saturating_add(16).min(batch_rows);
                        let chunk_rows = batch_end - batch_start;
                        let mut chunk_input = self.zeros_f32(checked_mul(
                            chunk_rows,
                            matrix.cols,
                            "Marlin Q6_K prompt input elements",
                        )?)?;
                        self.copy_f32_device_range(
                            input,
                            batch_start * matrix.cols,
                            &mut chunk_input,
                        )?;
                        let mut chunk_output = self.zeros_f32(checked_mul(
                            chunk_rows,
                            matrix.rows,
                            "Marlin Q6_K prompt output elements",
                        )?)?;
                        self.matmul_q6_k_marlin_f32_into_on_stream(
                            marlin,
                            &chunk_input,
                            chunk_rows,
                            &mut chunk_output,
                            None,
                        )?;
                        self.copy_f32_device_into_range(
                            &chunk_output,
                            output,
                            batch_start * matrix.rows,
                        )?;
                    }
                    Ok(())
                }
                CudaKQuantMatrixStorage::ExpandedF32 {
                    values_transposed, ..
                } => self.matmul_resident_rhs_device_into(
                    input,
                    batch_rows,
                    matrix.cols,
                    values_transposed,
                    matrix.rows,
                    output,
                ),
                CudaKQuantMatrixStorage::Q4K { .. } => Err(XrtError::InvalidTensor(
                    "Q6_K matmul received packed Q4_K storage".to_string(),
                )),
                CudaKQuantMatrixStorage::Q4KMarlin { .. } => Err(XrtError::InvalidTensor(
                    "Q6_K matmul received Marlin Q4_K storage".to_string(),
                )),
                CudaKQuantMatrixStorage::Q5K { .. } | CudaKQuantMatrixStorage::Q5KMarlin { .. } => {
                    Err(XrtError::InvalidTensor(
                        "Q6_K matmul received packed Q5_K storage".to_string(),
                    ))
                }
            }
        }

        pub fn add(&self, lhs: &[f32], rhs: &[f32]) -> Result<Vec<f32>> {
            let lhs = self.upload_f32(lhs)?;
            let rhs = self.upload_f32(rhs)?;
            self.add_device(&lhs, &rhs)
                .and_then(|output| self.download_f32(&output))
        }

        pub fn add_device(
            &self,
            lhs: &CudaF32Buffer,
            rhs: &CudaF32Buffer,
        ) -> Result<CudaF32Buffer> {
            if lhs.len() != rhs.len() {
                return Err(XrtError::Shape(format!(
                    "add inputs must have identical lengths, found {} and {}",
                    lhs.len(),
                    rhs.len()
                )));
            }
            if lhs.is_empty() {
                return self.zeros_f32(0);
            }

            let mut output = self.zeros_f32(lhs.len())?;
            self.add_device_into(lhs, rhs, &mut output)?;
            Ok(output)
        }

        pub fn add_device_into(
            &self,
            lhs: &CudaF32Buffer,
            rhs: &CudaF32Buffer,
            output: &mut CudaF32Buffer,
        ) -> Result<()> {
            if lhs.len() != rhs.len() {
                return Err(XrtError::Shape(format!(
                    "add inputs must have identical lengths, found {} and {}",
                    lhs.len(),
                    rhs.len()
                )));
            }
            expect_len(output.len(), lhs.len(), "add output")?;
            self.copy_f32_device(lhs, output)?;
            self.add_assign_device(output, rhs)
        }

        pub fn add_assign_device(
            &self,
            lhs: &mut CudaF32Buffer,
            rhs: &CudaF32Buffer,
        ) -> Result<()> {
            if lhs.len() != rhs.len() {
                return Err(XrtError::Shape(format!(
                    "add inputs must have identical lengths, found {} and {}",
                    lhs.len(),
                    rhs.len()
                )));
            }
            if lhs.is_empty() {
                return Ok(());
            }

            let n_u32 = to_u32(lhs.len(), "add element count")?;

            let func = self.function(self.modules.add, "elementwise_add_kernel")?;
            unsafe { func.launch(one_dim_launch(n_u32), (&mut lhs.data, &rhs.data, n_u32)) }
                .map_err(|err| cuda_error("failed to launch add kernel", err))?;
            Ok(())
        }

        /// Adds `rhs` into a same-length contiguous range of `lhs` without a
        /// temporary device-to-device copy.
        pub fn add_assign_device_subrange(
            &self,
            lhs: &mut CudaF32Buffer,
            lhs_offset: usize,
            rhs: &CudaF32Buffer,
        ) -> Result<()> {
            let lhs_end = lhs_offset.checked_add(rhs.len()).ok_or_else(|| {
                XrtError::Shape("add-assign device subrange overflowed".to_string())
            })?;
            if lhs_end > lhs.len() {
                return Err(XrtError::Shape(format!(
                    "add-assign device subrange [{lhs_offset}..{lhs_end}) exceeds destination length {}",
                    lhs.len()
                )));
            }
            if rhs.is_empty() {
                return Ok(());
            }
            let mut lhs_view = lhs
                .data
                .try_slice_mut(lhs_offset..lhs_end)
                .ok_or_else(|| XrtError::Cuda("failed to slice add destination".to_string()))?;
            let n_u32 = to_u32(rhs.len(), "add subrange element count")?;
            let func = self.function(self.modules.add, "elementwise_add_kernel")?;
            unsafe { func.launch(one_dim_launch(n_u32), (&mut lhs_view, &rhs.data, n_u32)) }
                .map_err(|err| cuda_error("failed to launch add subrange kernel", err))?;
            Ok(())
        }

        pub fn scaled_row_add_assign_device(
            &self,
            lhs: &mut CudaF32Buffer,
            packed_rhs: &CudaF32Buffer,
            rhs_offset: usize,
            scale: f32,
        ) -> Result<()> {
            let rhs_end = rhs_offset.checked_add(lhs.len()).ok_or_else(|| {
                XrtError::Runtime("scaled row add source range overflowed".to_string())
            })?;
            if rhs_end > packed_rhs.len() {
                return Err(XrtError::Shape(format!(
                    "scaled row add source range {rhs_offset}..{rhs_end} exceeds packed source length {}",
                    packed_rhs.len()
                )));
            }
            if lhs.is_empty() {
                return Ok(());
            }
            if !scale.is_finite() {
                return Err(XrtError::Model(format!(
                    "CUDA scaled row add multiplier must be finite, found {scale}"
                )));
            }

            let offset_u32 = to_u32(rhs_offset, "scaled row add source offset")?;
            let n_u32 = to_u32(lhs.len(), "scaled row add element count")?;
            let func = self.function(self.modules.add, "scaled_row_add_assign_kernel")?;
            unsafe {
                func.launch(
                    one_dim_launch(n_u32),
                    (&mut lhs.data, &packed_rhs.data, offset_u32, n_u32, scale),
                )
            }
            .map_err(|err| cuda_error("failed to launch scaled row add kernel", err))?;
            Ok(())
        }

        pub fn packed_rows_add_assign_device(
            &self,
            lhs: &mut CudaF32Buffer,
            packed_rhs: &CudaF32Buffer,
            row_offset: usize,
            row_count: usize,
        ) -> Result<()> {
            let source_start = row_offset.checked_mul(lhs.len()).ok_or_else(|| {
                XrtError::Runtime("packed row add source offset overflowed".to_string())
            })?;
            let source_len = row_count.checked_mul(lhs.len()).ok_or_else(|| {
                XrtError::Runtime("packed row add source length overflowed".to_string())
            })?;
            let source_end = source_start.checked_add(source_len).ok_or_else(|| {
                XrtError::Runtime("packed row add source range overflowed".to_string())
            })?;
            if source_end > packed_rhs.len() {
                return Err(XrtError::Shape(format!(
                    "packed row add source range {source_start}..{source_end} exceeds packed source length {}",
                    packed_rhs.len()
                )));
            }
            if lhs.is_empty() || row_count == 0 {
                return Ok(());
            }

            let row_offset_u32 = to_u32(row_offset, "packed row add source row offset")?;
            let row_count_u32 = to_u32(row_count, "packed row add source row count")?;
            let width_u32 = to_u32(lhs.len(), "packed row add row width")?;
            let func = self.function(self.modules.add, "packed_rows_add_assign_kernel")?;
            unsafe {
                func.launch(
                    one_dim_launch(width_u32),
                    (
                        &mut lhs.data,
                        &packed_rhs.data,
                        row_offset_u32,
                        row_count_u32,
                        width_u32,
                    ),
                )
            }
            .map_err(|err| cuda_error("failed to launch packed row add kernel", err))?;
            Ok(())
        }

        pub fn mul_device(
            &self,
            lhs: &CudaF32Buffer,
            rhs: &CudaF32Buffer,
        ) -> Result<CudaF32Buffer> {
            if lhs.len() != rhs.len() {
                return Err(XrtError::Shape(format!(
                    "mul inputs must have identical lengths, found {} and {}",
                    lhs.len(),
                    rhs.len()
                )));
            }
            if lhs.is_empty() {
                return self.zeros_f32(0);
            }

            let mut output = self.zeros_f32(lhs.len())?;
            self.mul_device_into(lhs, rhs, &mut output)?;
            Ok(output)
        }

        pub fn mul_device_into(
            &self,
            lhs: &CudaF32Buffer,
            rhs: &CudaF32Buffer,
            output: &mut CudaF32Buffer,
        ) -> Result<()> {
            if lhs.len() != rhs.len() {
                return Err(XrtError::Shape(format!(
                    "mul inputs must have identical lengths, found {} and {}",
                    lhs.len(),
                    rhs.len()
                )));
            }
            expect_len(output.len(), lhs.len(), "mul output")?;
            self.copy_f32_device(lhs, output)?;
            self.mul_assign_device(output, rhs)
        }

        pub fn mul_assign_device(
            &self,
            lhs: &mut CudaF32Buffer,
            rhs: &CudaF32Buffer,
        ) -> Result<()> {
            if lhs.len() != rhs.len() {
                return Err(XrtError::Shape(format!(
                    "mul inputs must have identical lengths, found {} and {}",
                    lhs.len(),
                    rhs.len()
                )));
            }
            if lhs.is_empty() {
                return Ok(());
            }

            let n_u32 = to_u32(lhs.len(), "mul element count")?;

            let func = self.function(self.modules.mul, "elementwise_mul_kernel")?;
            unsafe { func.launch(one_dim_launch(n_u32), (&mut lhs.data, &rhs.data, n_u32)) }
                .map_err(|err| cuda_error("failed to launch mul kernel", err))?;
            Ok(())
        }

        pub fn scale_assign_device(&self, values: &mut CudaF32Buffer, scale: f32) -> Result<()> {
            if values.is_empty() {
                return Ok(());
            }
            if !scale.is_finite() {
                return Err(XrtError::Model(format!(
                    "CUDA scalar multiplier must be finite, found {scale}"
                )));
            }

            let n_u32 = to_u32(values.len(), "scale element count")?;
            let func = self.function(self.modules.activation, "scale_assign_kernel")?;
            unsafe { func.launch(one_dim_launch(n_u32), (&mut values.data, n_u32, scale)) }
                .map_err(|err| cuda_error("failed to launch scale kernel", err))?;
            Ok(())
        }

        pub fn geglu_pytorch_tanh_assign_device(
            &self,
            gate: &mut CudaF32Buffer,
            up: &CudaF32Buffer,
        ) -> Result<()> {
            if gate.len() != up.len() {
                return Err(XrtError::Shape(format!(
                    "GeGLU inputs must have identical lengths, found {} and {}",
                    gate.len(),
                    up.len()
                )));
            }
            if gate.is_empty() {
                return Ok(());
            }

            let n_u32 = to_u32(gate.len(), "GeGLU element count")?;
            let func = self.function(self.modules.activation, "geglu_pytorch_tanh_kernel")?;
            unsafe { func.launch(one_dim_launch(n_u32), (&mut gate.data, &up.data, n_u32)) }
                .map_err(|err| cuda_error("failed to launch PyTorch tanh GeGLU kernel", err))?;
            Ok(())
        }

        pub fn logit_softcap_assign_device(
            &self,
            values: &mut CudaF32Buffer,
            softcap: f32,
        ) -> Result<()> {
            if values.is_empty() {
                return Ok(());
            }
            if !softcap.is_finite() || softcap <= 0.0 {
                return Err(XrtError::Model(format!(
                    "CUDA logit softcap must be finite and positive, found {softcap}"
                )));
            }

            let n_u32 = to_u32(values.len(), "logit softcap element count")?;
            let func = self.function(self.modules.activation, "logit_softcap_assign_kernel")?;
            unsafe { func.launch(one_dim_launch(n_u32), (&mut values.data, n_u32, softcap)) }
                .map_err(|err| cuda_error("failed to launch logit softcap kernel", err))?;
            Ok(())
        }

        pub fn image_bias_add_assign_device(
            &self,
            values: &mut CudaF32Buffer,
            bias: &CudaF32Buffer,
            rows: usize,
            width: usize,
        ) -> Result<()> {
            if width == 0 {
                return Err(XrtError::Shape(
                    "CUDA image bias width must be positive".to_string(),
                ));
            }
            let elements = checked_mul(rows, width, "CUDA image bias elements")?;
            expect_len(values.len(), elements, "CUDA image bias values")?;
            expect_len(bias.len(), width, "CUDA image bias vector")?;
            if elements == 0 {
                return Ok(());
            }
            let elements = to_u32(elements, "CUDA image bias elements")?;
            let function = self.function(self.modules.image, "xrt_image_bias_add")?;
            unsafe {
                function.launch(
                    one_dim_launch(elements),
                    (
                        &mut values.data,
                        &bias.data,
                        elements,
                        to_u32(width, "CUDA image bias width")?,
                    ),
                )
            }
            .map_err(|error| cuda_error("failed to launch CUDA image bias kernel", error))
        }

        pub fn image_layer_norm_device(
            &self,
            input: &CudaF32Buffer,
            rows: usize,
            width: usize,
            epsilon: f32,
        ) -> Result<CudaF32Buffer> {
            let elements = checked_mul(rows, width, "CUDA image LayerNorm elements")?;
            expect_len(input.len(), elements, "CUDA image LayerNorm input")?;
            if width == 0 || !epsilon.is_finite() || epsilon <= 0.0 {
                return Err(XrtError::Shape(format!(
                    "CUDA image LayerNorm requires positive width and epsilon, found width={width}, epsilon={epsilon}"
                )));
            }
            let mut output = self.zeros_f32(elements)?;
            if elements == 0 {
                return Ok(output);
            }
            let rows = to_u32(rows, "CUDA image LayerNorm rows")?;
            let function = self.function(self.modules.image, "xrt_image_layer_norm")?;
            unsafe {
                function.launch(
                    serial_row_launch(rows),
                    (
                        &input.data,
                        &mut output.data,
                        rows,
                        to_u32(width, "CUDA image LayerNorm width")?,
                        epsilon,
                    ),
                )
            }
            .map_err(|error| cuda_error("failed to launch CUDA image LayerNorm kernel", error))?;
            Ok(output)
        }

        #[allow(clippy::too_many_arguments)]
        pub fn image_affine_rows_assign_device(
            &self,
            values: &mut CudaF32Buffer,
            conditioning: &CudaF32Buffer,
            batch: usize,
            sequence: usize,
            width: usize,
            conditioning_stride: usize,
            scale_offset: usize,
            shift_offset: usize,
            scale_bias: f32,
        ) -> Result<()> {
            let rows = checked_mul(batch, sequence, "CUDA image affine rows")?;
            let elements = checked_mul(rows, width, "CUDA image affine elements")?;
            let conditioning_elements = checked_mul(
                batch,
                conditioning_stride,
                "CUDA image affine conditioning elements",
            )?;
            expect_len(values.len(), elements, "CUDA image affine values")?;
            expect_len(
                conditioning.len(),
                conditioning_elements,
                "CUDA image affine conditioning",
            )?;
            let scale_end = scale_offset.checked_add(width).ok_or_else(|| {
                XrtError::Shape("CUDA image affine scale range overflow".to_string())
            })?;
            let shift_end = shift_offset.checked_add(width).ok_or_else(|| {
                XrtError::Shape("CUDA image affine shift range overflow".to_string())
            })?;
            if batch == 0
                || sequence == 0
                || width == 0
                || scale_end > conditioning_stride
                || shift_end > conditioning_stride
                || !scale_bias.is_finite()
            {
                return Err(XrtError::Shape(
                    "CUDA image affine geometry or scale bias is invalid".to_string(),
                ));
            }
            let elements = to_u32(elements, "CUDA image affine elements")?;
            let function = self.function(self.modules.image, "xrt_image_affine_rows")?;
            unsafe {
                function.launch(
                    one_dim_launch(elements),
                    (
                        &mut values.data,
                        &conditioning.data,
                        elements,
                        to_u32(sequence, "CUDA image affine sequence")?,
                        to_u32(width, "CUDA image affine width")?,
                        to_u32(conditioning_stride, "CUDA image affine conditioning stride")?,
                        to_u32(scale_offset, "CUDA image affine scale offset")?,
                        to_u32(shift_offset, "CUDA image affine shift offset")?,
                        scale_bias,
                    ),
                )
            }
            .map_err(|error| cuda_error("failed to launch CUDA image affine kernel", error))
        }

