        let mixed_attention = device.download_f32(&mixed_attention_dev)?;
        let mut mixed_keys = Vec::with_capacity(key.len() * 2);
        mixed_keys.extend_from_slice(&key);
        mixed_keys.extend_from_slice(&roundtrip_key_2);
